class PontEditeur(QObject):
    """Pont JS <-> Python pour un éditeur HTML contenteditable, exposé côté
    JS sous le nom 'pyBridge' via QWebChannel (remplace le mécanisme
    cef.JavascriptBindings().SetFunction(...) de cefpython3).

    Chaque instance reçoit les callbacks Python à appeler ; le JS, lui,
    appelle toujours pyBridge.recevoir_html_courant(...) /
    pyBridge.debug_focus_etat(...) — les noms ne changent pas côté page
    HTML, seul le préfixe 'pyBridge.' est ajouté."""

    def __init__(self, recevoir_html=None, debug_focus=None, rendu_visuel_termine=None,
                 segments_traduction=None, parent=None):
        super().__init__(parent)
        self._recevoir_html = recevoir_html
        self._debug_focus = debug_focus
        self._rendu_visuel_termine = rendu_visuel_termine
        self._segments_traduction = segments_traduction

    @Slot(int, str)
    def segmentsTraduction(self, jeton, passages_json):
        """Bouton Traduire de la rédaction (11/10/2026) : passages du texte
        rédigé (citation exclue) à traduire."""
        if self._segments_traduction:
            self._segments_traduction(jeton, passages_json)

    @Slot(str)
    def recevoir_html_courant(self, html):
        if self._recevoir_html:
            self._recevoir_html(html)

    @Slot(str)
    def debug_focus_etat(self, info):
        if self._debug_focus:
            self._debug_focus(info)

    @Slot(int)
    def renduVisuelTermine(self, nb_images):
        """Voile blanc à l'ouverture de la fenêtre de rédaction (correctif
        du 20/08/2026, perdu à la migration PySide6 du 29/08, réintroduit
        le 31/08) : appelé côté JS une fois que toutes les images du corps
        édité (citation d'un mail renvoyé/répondu/transféré) ont fini
        d'être décodées et peintes — voir _mesurerRenduVisuelEditeur."""
        if self._rendu_visuel_termine:
            self._rendu_visuel_termine(nb_images)


def _page_mail_locale(client_mail):
    """Vrai si le panneau de lecture affiche exactement la page que COURRIER
    vient d'écrire (_afficher_dans_cef : mail ou aperçu de PJ, protégée par
    la CSP), faux pour un site web externe ou tout autre fichier local (une
    PJ .html ouverte en externe vit aussi dans DOSSIER_APERCU, sans CSP).
    Voir _reserve_page_mail."""
    try:
        url = client_mail.webview.url()
        attendu = getattr(client_mail, '_temp_html', None)
        if not attendu or not url.isLocalFile():
            return False
        return (os.path.normcase(os.path.realpath(url.toLocalFile()))
                == os.path.normcase(os.path.realpath(attendu)))
    except Exception:
        return False

def _reserve_page_mail(methode):
    """Sécurité (09/10/2026) : le pont pyBridge est aussi joignable depuis
    les sites web ouverts dans le panneau (SCRIPT_BADGE_IMAGES_EXTERNES).
    N'importe quel site pouvait donc ouvrir une pièce jointe du mail
    courant, l'enregistrer, supprimer le mail (touche_pressee)... Les
    méthodes décorées ne répondent plus qu'aux pages de COURRIER."""
    import functools

    @functools.wraps(methode)
    def enveloppe(self, *args):
        if not _page_mail_locale(self._cm):
            print(f"[SECURITE] pyBridge.{methode.__name__} refusé depuis {self._cm.webview.url().toString()[:200]}")
            return None
        return methode(self, *args)
    return enveloppe

class PontLecture(QObject):
    """Pont JS <-> Python pour le panneau de lecture (ClientMail), exposé
    côté JS sous le nom 'pyBridge'. Remplace les cef.JavascriptBindings
    (7 fonctions pièces-jointes/navigation) ET le relais clavier qu'assurait
    CefKeyboardHandler (CEF interceptait Flèches/Suppr/Ctrl+A/Ctrl+R au
    niveau natif avant que Qt ne les voie ; ici un keydown JS les relaie)."""

    def __init__(self, client_mail, parent=None):
        super().__init__(parent)
        self._cm = client_mail

    @Slot(int)
    @_reserve_page_mail
    def ouvrirPieceJointe(self, index):
        self._cm._ouvrir_pj_depuis_js(index)

    @Slot()
    @_reserve_page_mail
    def enregistrerPiecesJointes(self):
        self._cm._enregistrer_pieces_jointes()

    @Slot()
    @_reserve_page_mail
    def enregistrerTout(self):
        self._cm._enregistrer_tout_direct()

    @Slot()
    @_reserve_page_mail
    def ouvrirMailReponse(self):
        self._cm._ouvrir_mail_reponse_depuis_js()

    @Slot(int, str)
    @_reserve_page_mail
    def traduireMail(self, jeton, passages_json):
        """Bouton TRADUIRE du bandeau (11/10/2026)."""
        self._cm._traduire_mail_depuis_js(jeton, passages_json)

    @Slot()
    @_reserve_page_mail
    def revenirCorpsPJ(self):
        self._cm._revenir_corps_mail_pj()

    @Slot(int)
    @_reserve_page_mail
    def ouvrirPJExterneBinding(self, index):
        self._cm._ouvrir_pj_externe_depuis_js(index)

    @Slot()
    @_reserve_page_mail
    def retournerOrigine(self):
        self._cm._retourner_origine_depuis_js()

    @Slot()
    @_reserve_page_mail
    def recharger_mail(self):
        """Bouton RECHARGER intégré au bandeau du mail lui-même."""
        self._cm._recharger_mail_courant()

    @Slot(str)
    @_reserve_page_mail
    def imprimer_pdf(self, sujet):
        """Bouton PDF intégré au bandeau du mail (à côté de RECHARGER)."""
        self._cm._imprimer_mail_pdf(sujet)

    @Slot()
    def traduirePageWeb(self):
        """Bouton TRADUIRE injecté sur une page web (12/10/2026). N'importe
        quel site peut appeler ce pont : le seul effet possible est d'ouvrir
        la fenêtre de choix, où rien ne part sans le clic de l'utilisateur."""
        QTimer.singleShot(0, self._cm._traduire_page_web)

    @Slot(int)
    def lireVideoWeb(self, index):
        """Bouton "Lire la vidéo" injecté sur une page externe dont la
        vidéo est illisible par QtWebEngine (voir ExtracteurVideoWeb)."""
        self._cm._lire_video_web(index)

    @Slot(int)
    def naviguerImagePJ(self, sens):
        """Flèche gauche/droite pressée sur une photo en pièce jointe
        (voir _img_pj_voisine)."""
        QTimer.singleShot(0, lambda: self._cm._img_pj_voisine(sens))

    @Slot(str, str)
    def videosPageWeb(self, url_page, json_videos):
        """Adresses de vidéos relevées par la page elle-même (Facebook,
        voir _chercher_video_dans_page)."""
        self._cm._sur_videos_page_web(url_page, json_videos)

    @Slot(str, float)
    def signalerPositionVideo(self, url, position):
        """Reprise de lecture vidéo (21/08/2026, refondu le 30/08/2026) :
        la page externe elle-même pousse sa position de lecture ici, via
        le script SCRIPT_BADGE_IMAGES_EXTERNES (fonction suivreVideo côté
        JS, throttlée à ~2s + envoi immédiat sur pause/beforeunload).
        Remplace un sondage périodique Python->JS (runJavaScript) qui
        provoquait des flashs visibles en bas de page pendant la lecture,
        puis une tentative de capture ponctuelle synchrone au moment de
        changer de mail qui perdait quasi systématiquement la course
        contre le rechargement du webview (runJavaScript est toujours
        asynchrone côté QtWebEngine)."""
        cle = getattr(self._cm, '_cle_cache_html_affichee', None)
        nav = getattr(self._cm, '_navigation_externe_par_mail', None)
        if not cle or not nav or cle not in nav:
            return
        entree = nav[cle]
        if entree.get("url") != url:
            return  # signal tardif d'une page déjà quittée
        entree["position"] = position

    @Slot(int)
    def renduVisuelTermine(self, nb_images):
        """Appelé côté JS une fois que TOUTES les images du mail ont fini
        d'être décodées et qu'une frame de compositing a eu lieu — mesure
        ajoutée le 27/07/2026 car loadFinished (didFinishLoad) se déclenche
        sur l'événement 'load' du DOM, pas sur la peinture réelle à l'écran :
        pour un mail à plusieurs très grosses images embarquées en base64,
        le décodage + la composition (surtout en rendu logiciel forcé)
        continuent bien après 'load', créant un écart mesuré entre
        loadFinished et ce que l'utilisateur voit vraiment se terminer."""
        import time
        t_debut = getattr(self._cm, '_t_debut_rendu_webview', None)
        if t_debut is not None:
            ecoule = time.time() - t_debut
            # Même garde-fou que _sur_chargement_termine_lecture (29/07/2026)
            if ecoule > 60:
                print(f"[PERF-RENDU-VISUEL-REEL] valeur ignorée ({ecoule:.0f}s, "
                      f"signal tardif sans rapport avec un nouveau webview.load())")
            else:
                print(f"[PERF-RENDU-VISUEL-REEL] webview.load -> toutes images peintes = {ecoule:.3f}s (nb_images={nb_images})")
        # Voile blanc au clic sur un mail (30/08/2026, remonté par l'utilisateur
        # comme le bug le plus flagrant suite à la migration PySide6) : voir
        # _reactiver_rendu_lecture pour le mécanisme (mise à jour à l'écran
        # coupée pendant le chargement, réactivée seulement ici, une fois la
        # peinture réelle terminée).
        if hasattr(self._cm, '_reactiver_rendu_lecture'):
            self._cm._reactiver_rendu_lecture(self._cm._generation_rendu_lecture)

    @Slot(str)
    def telechargerImage(self, src):
        """Icône de téléchargement en un clic superposée sur les images du
        corps du mail (façon extension Firefox 'Double click image
        downloader'), ajoutée le 20/07/2026."""
        self._cm._telecharger_image_survol(src)

    @Slot(str, str)
    @_reserve_page_mail
    def ouvrirAdresseCliquee(self, adresse, nom):
        """Clic sur une adresse dans le bandeau De/À/Cc/Cci — ouvre le
        carnet d'adresses pré-rempli, prêt à choisir le dossier et
        enregistrer (ajouté le 20/07/2026)."""
        self._cm._sur_clic_adresse_dans_bandeau(adresse, nom)

    @Slot(str, bool)
    @_reserve_page_mail
    def touche_pressee(self, touche, ctrl):
        """Relais clavier depuis le JS de la page — remplace
        CefKeyboardHandler.OnPreKeyEvent (qui interceptait ces mêmes touches
        directement dans CEF avant que Qt ne les voie)."""
        cm = self._cm
        if touche == 'Delete':
            QTimer.singleShot(0, cm.supprimer_message)
        elif touche == 'a' and ctrl:
            if cm._survol_liste:
                cm.selectionner_tout()
        elif touche == 'r' and ctrl:
            QTimer.singleShot(0, cm.repondre)
        elif touche == 'ArrowUp':
            cm._naviguer_haut()
        elif touche == 'ArrowDown':
            cm._naviguer_bas()



