DOSSIER_STORAGE = os.path.join(DOSSIER_APP, "Storage")

def _chemin_cache_arbo(compte):
    """Cache disque de l'arborescence des dossiers d'un compte —
    manquait jusqu'ici (03/09/2026, ajouté) : contrairement aux mails
    eux-mêmes (toujours affichés depuis le disque, jamais en direct),
    la LISTE des dossiers elle-même était toujours relue en direct au
    changement de compte, sans jamais rien garder sur disque. Invisible
    sur IMAP (un LIST sur connexion déjà ouverte coûte presque rien),
    très visible sur Graph (dizaines de requêtes HTTPS séparées, 4-8s).
    Principe fondateur de COURRIER : TOUT sur le disque, y compris ceci
    — l'arbre s'affiche maintenant instantanément depuis ce cache, puis
    se corrige en silence si le direct diffère (même logique que
    ChargeurMessagesCache puis ChargeurMessages pour les mails)."""
    adresse = compte["adresse"].replace("@", "_at_")
    dossier_compte = os.path.join(DOSSIER_STORAGE, adresse)
    os.makedirs(dossier_compte, exist_ok=True)
    return os.path.join(dossier_compte, "_arborescence.json")

def sauvegarder_cache_arbo(compte, dossiers, tuples_map):
    try:
        data = {"dossiers": dossiers, "map": list(tuples_map)}
        with open(_chemin_cache_arbo(compte), "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False)
    except Exception:
        pass

def charger_cache_arbo(compte):
    """Retourne (dossiers, tuples_map) depuis le cache disque, ou
    (None, None) si absent (tout premier lancement pour ce compte)."""
    chemin = _chemin_cache_arbo(compte)
    if not os.path.exists(chemin):
        return None, None
    try:
        with open(chemin, "r", encoding="utf-8") as f:
            data = json.load(f)
        dossiers = data.get("dossiers")
        tuples_map = [tuple(t) for t in data.get("map", [])]
        return dossiers, tuples_map
    except Exception:
        return None, None

