    "amazon-adsystem.com", "outbrain.com", "taboola.com", "criteo.com",
    "criteo.net", "adnxs.com", "adsrvr.org", "media.net", "adform.net",
    "smartadserver.com", "pubmatic.com", "rubiconproject.com",
    "casalemedia.com", "openx.net", "yieldmanager.com", "yieldmanager.net",
    "moatads.com", "scorecardresearch.com", "quantserve.com",
    "adroll.com", "advertising.com", "adsafeprotected.com",
    "3lift.com", "bidswitch.net", "contextweb.com", "gumgum.com",
