class _FluxDouble:
    """Écrit à la fois vers le flux d'origine (console) et vers un fichier
    de log, ligne par ligne, avec horodatage. Utilisé pour remplacer
    sys.stdout/sys.stderr sans toucher au reste du code."""

    def __init__(self, flux_origine, chemin_log):
        self._flux_origine = flux_origine
        self._chemin_log = chemin_log

    def write(self, texte):
        try:
            self._flux_origine.write(texte)
        except Exception:
            pass
        if texte and texte.strip():
            try:
                horodatage = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                with open(self._chemin_log, "a", encoding="utf-8") as f:
                    for ligne in texte.splitlines():
                        if ligne.strip():
                            f.write(f"[{horodatage}] {ligne}\n")
            except Exception:
                pass

    def flush(self):
        try:
            self._flux_origine.flush()
        except Exception:
            pass

    def isatty(self):
        try:
            return self._flux_origine.isatty()
        except Exception:
            return False


def _purger_vieux_logs(dossier, jours=30):
    """Supprime les fichiers de log de plus de `jours` jours, pour éviter
    une accumulation illimitée (un fichier par jour d'utilisation)."""
    try:
        seuil = datetime.datetime.now().timestamp() - jours * 86400
        for nom in os.listdir(dossier):
            chemin = os.path.join(dossier, nom)
            try:
                if os.path.isfile(chemin) and os.path.getmtime(chemin) < seuil:
                    os.remove(chemin)
            except Exception:
                pass
    except Exception:
        pass


try:
    _purger_vieux_logs(DOSSIER_LOGS)
    _nom_log = f"courrier_{datetime.datetime.now().strftime('%Y-%m-%d')}.log"
    _chemin_log_jour = os.path.join(DOSSIER_LOGS, _nom_log)
    sys.stdout = _FluxDouble(sys.stdout, _chemin_log_jour)
    sys.stderr = _FluxDouble(sys.stderr, _chemin_log_jour)
except Exception:
    pass
