def prochaine_occurrence(dt, periodicite):
    """Décale une date/heure d'une période de récurrence (13/08/2026,
    combo Périodicité de l'agenda demandé par l'utilisateur). Gère le cas
    des mois à durée variable (ex. 31 janvier + 1 mois -> 28/29 février,
    pas une erreur ou un débordement sur mars) en recalculant le dernier
    jour du mois cible plutôt qu'en ajoutant bêtement des jours."""
    if periodicite == "jour":
        return dt + datetime.timedelta(days=1)
    if periodicite == "semaine":
        return dt + datetime.timedelta(weeks=1)
    if periodicite == "mois":
        mois = dt.month + 1
        annee = dt.year + (1 if mois > 12 else 0)
        mois = 1 if mois > 12 else mois
        import calendar
        dernier_jour = calendar.monthrange(annee, mois)[1]
        jour = min(dt.day, dernier_jour)
        return dt.replace(year=annee, month=mois, day=jour)
    if periodicite == "an":
        try:
            return dt.replace(year=dt.year + 1)
        except ValueError:
            # 29 février sur une année non bissextile -> 28 février
            return dt.replace(year=dt.year + 1, day=28)
    return dt  # "aucune" ou valeur inconnue : ne devrait jamais être appelé

def parser_mailto(uri):
    """Découpe un lien mailto: (RFC 6068) en ses composantes utiles
    (15/08/2026, demandé par l'utilisateur — COURRIER enregistré comme
    client mail par défaut de Windows). Renvoie toujours un dict avec ces
    5 clés, vides si absentes du lien."""
    from urllib.parse import parse_qs, unquote
    reste = uri[len("mailto:"):] if uri.lower().startswith("mailto:") else uri
    if "?" in reste:
        destinataire_brut, requete = reste.split("?", 1)
    else:
        destinataire_brut, requete = reste, ""
    parametres = parse_qs(requete, keep_blank_values=True)
    def _valeur(cle):
        v = parametres.get(cle) or parametres.get(cle.capitalize()) or parametres.get(cle.upper())
        return unquote(v[0]) if v else ""
    destinataire = unquote(destinataire_brut)
    # mailto: autorise un paramètre "to" en plus de la partie avant le "?"
    # (rare, mais prévu par la RFC — on les combine si les deux sont là).
    to_supplementaire = _valeur("to")
    if to_supplementaire:
        destinataire = f"{destinataire}, {to_supplementaire}" if destinataire else to_supplementaire
    return {
        "to": destinataire,
        "subject": _valeur("subject"),
        "body": _valeur("body"),
        "cc": _valeur("cc"),
        "bcc": _valeur("bcc"),
    }

def enregistrer_client_mail_windows():
    """Enregistre COURRIER comme client mail auprès de Windows (mailto: +
    apparition dans Paramètres > Applications par défaut > Messagerie),
    sans nécessiter de compilation en .exe — la commande enregistrée
    appelle directement pythonw.exe sur ce script (15/08/2026, demandé par
    l'utilisateur, suite à un clic sur un lien mail qui ouvrait Foxmail au
    lieu de COURRIER). Écrit dans HKEY_CURRENT_USER (pas besoin des droits
    administrateur, contrairement à HKEY_LOCAL_MACHINE). Appelé une seule
    fois, manuellement, via l'argument --enregistrer-mailto (voir le bloc
    __main__ tout en bas du fichier) — jamais au démarrage normal.

    Complété le 16/08/2026 (remonté par l'utilisateur, capture d'écran à
    l'appui) : COURRIER n'apparaissait pas dans le panneau de configuration
    classique "Définir vos programmes par défaut" — et Foxmail non plus,
    alors que c'est bien lui qui s'ouvrait sur un clic mailto:. Ce panneau
    classique ne lit apparemment, sur cette édition de Windows, que
    HKEY_LOCAL_MACHINE\\SOFTWARE\\RegisteredApplications (inscription
    machine, nécessite les droits administrateur) — pas l'équivalent par
    utilisateur (HKCU) utilisé ci-dessus. Foxmail lui-même n'y apparaissant
    pas non plus tout en étant fonctionnel, il a dû s'approprier
    directement l'association mailto: sans passer par ce mécanisme
    "propre". Fait pareil ci-dessous : écrit directement dans
    HKCU\\Software\\Classes\\mailto\\shell\\open\\command, qui prend effet
    immédiatement pour resoudre mailto: SAUF si une préférence "UserChoice"
    protégée existe déjà pour ce protocole (mécanisme de sécurité Windows
    8+ qui empêche justement un programme de se l'approprier
    silencieusement par-dessus un autre) — dans ce cas, un message
    l'indique : il faudra alors changer le choix manuellement via les
    Paramètres Windows (si ce panneau existe sur cette édition IoT) ou
    désinstaller/désactiver Foxmail."""
    import winreg
    chemin_script = os.path.abspath(__file__)
    dossier_script = os.path.dirname(chemin_script)
    pythonw = os.path.join(sys.exec_prefix, "pythonw.exe")
    if not os.path.exists(pythonw):
        pythonw = sys.executable  # repli : python.exe (garde la console visible)
    icone = os.path.join(DOSSIER_APP, "courrier.ico")
    if not os.path.exists(icone):
        icone = pythonw
    commande_ouverture = f'"{pythonw}" "{chemin_script}"'
    commande_mailto = f'"{pythonw}" "{chemin_script}" "%1"'
    if getattr(sys, "frozen", False):
        commande_ouverture = f'"{sys.executable}"'
        commande_mailto = f'"{sys.executable}" "%1"'
    nom_appli = "COURRIER"

    def _creer_cle(chemin_complet, valeurs):
        cle = winreg.CreateKeyEx(winreg.HKEY_CURRENT_USER, chemin_complet)
        for nom_valeur, valeur in valeurs.items():
            winreg.SetValueEx(cle, nom_valeur, 0, winreg.REG_SZ, valeur)
        winreg.CloseKey(cle)

    base = rf"SOFTWARE\Clients\Mail\{nom_appli}"
    _creer_cle(base, {"": nom_appli, "LocalizedString": nom_appli})
    _creer_cle(base + r"\DefaultIcon", {"": icone})
    _creer_cle(base + r"\shell\open\command", {"": commande_ouverture})
    _creer_cle(base + r"\Protocols\mailto\shell\open\command", {"": commande_mailto})
    _creer_cle(base + r"\Capabilities\URLAssociations", {"mailto": f"{nom_appli}.mailto"})
    _creer_cle(rf"SOFTWARE\Classes\{nom_appli}.mailto\shell\open\command", {"": commande_mailto})
    _creer_cle(base + r"\Capabilities", {
        "ApplicationName": nom_appli,
        "ApplicationDescription": "Client mail COURRIER",
        "ApplicationIcon": icone,
    })
    # Fait apparaître COURRIER dans Paramètres > Applications par défaut
    # (fonctionne pour le panneau moderne "Applications par défaut" quand
    # il existe ; pas forcément pour le panneau classique "Définir vos
    # programmes par défaut" sur cette édition IoT — voir docstring).
    _creer_cle(r"SOFTWARE\RegisteredApplications", {nom_appli: base + r"\Capabilities"})

    # Appropriation directe de mailto: (16/08/2026) — même mécanisme que
    # Foxmail apparemment, pour que ça fonctionne réellement tout de suite,
    # indépendamment de tout panneau de sélection.
    deja_impose = False
    try:
        cle_userchoice = winreg.OpenKey(
            winreg.HKEY_CURRENT_USER,
            r"SOFTWARE\Microsoft\Windows\Shell\Associations\UrlAssociations\MAILTO\UserChoice"
        )
        winreg.CloseKey(cle_userchoice)
        deja_impose = True
    except FileNotFoundError:
        pass
    except Exception:
        pass
    _creer_cle(r"SOFTWARE\Classes\mailto", {"": f"{nom_appli}.mailto", "URL Protocol": ""})
    _creer_cle(r"SOFTWARE\Classes\mailto\shell\open\command", {"": commande_mailto})

    print(f"[MAILTO] COURRIER enregistré comme client mail (commande : {commande_mailto}).")
    if deja_impose:
        print("[MAILTO] ATTENTION : une préférence Windows protégée (UserChoice) existe déjà "
              "pour mailto: — probablement celle de Foxmail. Windows empêche un programme de "
              "la remplacer automatiquement (sécurité). Il faut la changer manuellement : soit "
              "via Paramètres > Applications > Applications par défaut > Messagerie si ce "
              "panneau existe sur cette édition Windows, soit en désinstallant/désactivant "
              "Foxmail, soit en supprimant cette clé de registre à la main puis en relançant "
              "cet enregistrement.")
    else:
        print("[MAILTO] Aucune préférence Windows protégée trouvée pour mailto: — "
              "l'appropriation directe devrait suffire, testez dès maintenant un lien mailto:.")

