def _parser_date_flux(date_brute):
    """Essaie plusieurs formats de date (RSS RFC822, Atom ISO8601) — renvoie
    un datetime naïf en local, ou None si non reconnu (l'appelant utilise
    alors l'heure de la vérification comme repli)."""
    if not date_brute:
        return None
    from email.utils import parsedate_to_datetime
    try:
        dt = parsedate_to_datetime(date_brute)
        if dt.tzinfo is not None:
            dt = dt.astimezone().replace(tzinfo=None)
        return dt
    except Exception:
        pass
    try:
        import datetime as _dt_mod
        texte = date_brute.strip().replace("Z", "+00:00")
        dt = _dt_mod.datetime.fromisoformat(texte)
        if dt.tzinfo is not None:
            dt = dt.astimezone().replace(tzinfo=None)
        return dt
    except Exception:
        return None

def parser_flux_rss(contenu_xml):
    """Parse un flux RSS 2.0 ou Atom et renvoie {"site_lien","site_description",
    "articles": [{"guid","titre","lien","resume","date_brute","image","auteur"}, ...]}
    dans l'ordre fourni par le flux (pas retrié) — chaque article n'a pas
    forcément tous les champs selon ce que le flux fournit réellement.

    "image" (18/08/2026, rendu façon Blogtrottr) : miniature/visuel de
    l'article si le flux en fournit une, cherchée dans l'ordre le plus
    courant chez les flux vidéo/blog : <enclosure type="image/...">,
    <media:thumbnail>, <media:content type="image/...">, et en dernier
    recours la première <img> trouvée dans le résumé HTML lui-même.

    "resume" (19/08/2026, complété après comparaison directe avec
    Blogtrottr sur un vrai flux — celui-ci affichait l'article ENTIER,
    pas juste un résumé) : privilégie désormais <content:encoded> (balise
    standard, très répandue notamment sur les flux WordPress, qui porte
    le contenu HTML complet de l'article) quand le flux la fournit, avec
    repli sur <description>/<summary> sinon — Blogtrottr fait
    vraisemblablement la même chose, d'où l'écart observé.

    "auteur" (19/08/2026, ajouté pour la ligne "par X" façon Blogtrottr) :
    <dc:creator> (très répandu, notamment WordPress) ou <author> selon ce
    que le flux fournit."""
    import xml.etree.ElementTree as ET
    import re as _re_img
    resultat = {"site_lien": "", "site_description": "", "articles": []}
    try:
        racine = ET.fromstring(contenu_xml)
    except Exception:
        return resultat

    ns_media = {"media": "http://search.yahoo.com/mrss/"}
    ns_content = {"content": "http://purl.org/rss/1.0/modules/content/"}
    ns_dc = {"dc": "http://purl.org/dc/elements/1.1/"}

    def _image_depuis_media(noeud):
        vignette = noeud.find(".//media:thumbnail", ns_media)
        if vignette is not None and vignette.get("url"):
            return vignette.get("url")
        for enc in noeud.findall(".//enclosure"):
            if (enc.get("type") or "").startswith("image/") and enc.get("url"):
                return enc.get("url")
        for contenu_media in noeud.findall(".//media:content", ns_media):
            if (contenu_media.get("type") or "").startswith("image/") and contenu_media.get("url"):
                return contenu_media.get("url")
            sous_vignette = contenu_media.find("media:thumbnail", ns_media)
            if sous_vignette is not None and sous_vignette.get("url"):
                return sous_vignette.get("url")
        vignette_itunes = noeud.find(".//{http://www.itunes.com/dtds/podcast-1.0.dtd}image")
        if vignette_itunes is not None and vignette_itunes.get("href"):
            return vignette_itunes.get("href")
        return ""

    def _image_depuis_html(html_brut):
        m = _re_img.search(r'<img[^>]+src=["\']([^"\']+)["\']', html_brut or "")
        return m.group(1) if m else ""

    def _contenu_complet_rss(it, description_repli):
        contenu = (it.findtext("content:encoded", default="", namespaces=ns_content) or "").strip()
        return contenu or description_repli

    def _auteur_rss(it):
        return (it.findtext("dc:creator", default="", namespaces=ns_dc)
                or it.findtext("author") or "").strip()

    canal = racine.find("channel")
    if canal is not None or racine.tag.lower().endswith("rss"):
        if canal is not None:
            resultat["site_lien"] = (canal.findtext("link") or "").strip()
            resultat["site_description"] = (canal.findtext("description") or "").strip()
        items = (canal.findall("item") if canal is not None else racine.findall(".//item"))
        for it in items:
            titre = (it.findtext("title") or "").strip()
            lien = (it.findtext("link") or "").strip()
            guid = (it.findtext("guid") or lien or titre).strip()
            description = (it.findtext("description") or "").strip()
            resume = _contenu_complet_rss(it, description)
            date_brute = (it.findtext("pubDate") or "").strip()
            image = _image_depuis_media(it) or _image_depuis_html(resume)
            auteur = _auteur_rss(it)
            if titre or lien:
                resultat["articles"].append({"guid": guid, "titre": titre, "lien": lien,
                                              "resume": resume, "date_brute": date_brute,
                                              "image": image, "auteur": auteur})
        return resultat

    # Atom (espace de noms présent ou non selon les flux)
    ns = {"a": "http://www.w3.org/2005/Atom"}
    liens_feed = racine.findall("a:link", ns) or racine.findall("link")
    lien_alternate = next((l.get("href", "") for l in liens_feed if l.get("rel") in (None, "alternate")), "")
    resultat["site_lien"] = lien_alternate or (liens_feed[0].get("href", "") if liens_feed else "")
    resultat["site_description"] = (racine.findtext("a:subtitle", default="", namespaces=ns)
                                     or racine.findtext("subtitle") or "").strip()
    entrees = racine.findall("a:entry", ns) or racine.findall("entry")
    for e in entrees:
        titre = (e.findtext("a:title", default="", namespaces=ns) or e.findtext("title") or "").strip()
        lien_el = e.find("a:link", ns)
        if lien_el is None:
            lien_el = e.find("link")
        lien = lien_el.get("href", "") if lien_el is not None else ""
        guid = (e.findtext("a:id", default="", namespaces=ns) or e.findtext("id") or lien or titre).strip()
        # Atom fournit déjà volontiers le contenu complet via <content> —
        # préféré à <summary> (résumé court) quand les 2 sont présents.
        resume = (e.findtext("a:content", default="", namespaces=ns) or e.findtext("content")
                  or e.findtext("a:summary", default="", namespaces=ns) or e.findtext("summary") or "").strip()
        date_brute = (e.findtext("a:published", default="", namespaces=ns) or e.findtext("published")
                      or e.findtext("a:updated", default="", namespaces=ns) or e.findtext("updated") or "").strip()
        image = _image_depuis_media(e) or _image_depuis_html(resume)
        auteur_el = e.find("a:author/a:name", ns)
        if auteur_el is None:
            auteur_el = e.find("author/name")
        auteur = (auteur_el.text or "").strip() if auteur_el is not None else ""
        if titre or lien:
            resultat["articles"].append({"guid": guid, "titre": titre, "lien": lien,
                                          "resume": resume, "date_brute": date_brute,
                                          "image": image, "auteur": auteur})
    return resultat

# Verrou global partagé (19/08/2026, remonté par l'utilisateur : un flux
# — KTM Presse — s'est remis à redéposer TOUS ses articles à plusieurs
# reprises, alors qu'il n'a jamais utilisé "Récupérer d'anciens articles").
# Cause probable trouvée en creusant : il existe 3 déclencheurs indépendants
# d'une vérification RSS (le minuteur périodique de 30 min dans ClientMail,
# et les 2 boutons manuels "Vérifier maintenant"/"Récupérer d'anciens
# articles" de la boîte de dialogue) — seul le minuteur périodique avait un
# garde-fou contre le chevauchement, PAS les 2 boutons manuels. Si l'un
# d'eux se déclenche PENDANT que le minuteur (ou un autre bouton) tourne
# déjà, 2 threads chargent alors chacun leur propre copie de
# abonnements_rss.json, la modifient indépendamment, et le dernier à
# sauvegarder écrase le travail de l'autre — pouvant effacer la mise à jour
# de "items_vus" faite par le premier thread, faisant réapparaître comme
# "nouveaux" des articles pourtant déjà vus lors d'une vérification
# suivante. Un verrou global, partagé entre les 3 déclencheurs (au lieu
# d'un garde-fou local à chacun), empêche ce chevauchement quelle que soit
# la combinaison de déclencheurs en cause.
_verrou_rss_global = {"en_cours": False}

# Programme de mise à jour d'un flux (28/09/2026, demandé par l'utilisateur
# — pouvoir se fabriquer soi-même un flux à partir d'un site qui n'en
# propose pas : un petit script lit la page et écrit un fichier .xml local,
# auquel on s'abonne avec une adresse file:///C:/.../flux.xml). Chaque flux
# peut désigner un programme (.py, .bat, .exe...) lancé juste avant sa
# vérification, au plus une fois par période choisie dans la fenêtre RSS
# (0 = à chaque vérification). Réglages mémorisés sur le flux lui-même
# ("programme", "programme_periode" en minutes, "programme_dernier").

# ── Recherche de flux à partir d'une adresse de site (10/10/2026) ─────────
_UA_RECHERCHE_FLUX = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                      "(KHTML, like Gecko) Chrome/140.0.0.0 Safari/537.36")
_CHEMINS_FLUX_HABITUELS = ("/feed", "/feed/", "/rss", "/rss/", "/rss.xml", "/feed.xml",
                           "/atom.xml", "/index.xml", "/?feed=rss2", "/feeds/posts/default")

def _telecharger_pour_flux(url, timeout=15, limite=3_000_000):
    """(adresse finale après redirections, octets) — lève une exception en cas d'échec."""
    import urllib.request
    requete = urllib.request.Request(url, headers={
        "User-Agent": _UA_RECHERCHE_FLUX,
        "Accept": "application/rss+xml, application/atom+xml, application/xml, text/xml, text/html;q=0.9, */*;q=0.8"})
    with urllib.request.urlopen(requete, timeout=timeout, context=CONTEXTE_SSL) as r:
        return r.geturl(), r.read(limite)

def _titre_si_flux(contenu):
    """Titre du flux si contenu est un flux RSS/Atom lisible, sinon None."""
    import xml.etree.ElementTree as ET
    debut = contenu[:2000].lstrip().lower()
    if not (b"<rss" in debut or b"<feed" in debut or b"<rdf:rdf" in debut or debut.startswith(b"<?xml")):
        return None
    try:
        racine = ET.fromstring(contenu)
    except Exception:
        return None
    nom = racine.tag.split("}")[-1].lower()
    if nom == "rss":
        canal = racine.find("channel")
        return ((canal.findtext("title") if canal is not None else "") or "").strip() or "(flux sans titre)"
    if nom == "feed":
        titre = racine.find("{http://www.w3.org/2005/Atom}title")
        return ((titre.text if titre is not None else "") or "").strip() or "(flux sans titre)"
    if nom == "rdf":
        for enfant in racine:
            if enfant.tag.split("}")[-1].lower() == "channel":
                for e in enfant:
                    if e.tag.split("}")[-1].lower() == "title":
                        return (e.text or "").strip() or "(flux sans titre)"
        return "(flux sans titre)"
    return None

def chercher_flux_depuis_url(adresse):
    """[(titre, url_du_flux, nb_articles)] des flux RSS/Atom d'un site — adresse donnée
    telle quelle si c'est déjà un flux, sinon flux annoncés par la page
    (<link rel="alternate" ...>), sinon adresses habituelles. Chaque flux
    est vérifié (téléchargé et lisible). Fonction bloquante : à appeler
    depuis un fil de fond (ChercheurFluxRSS)."""
    import re as _re
    from html import unescape
    from urllib.parse import urljoin, urlsplit
    adresse = adresse.strip()
    if not _re.match(r"^https?://", adresse, _re.IGNORECASE):
        adresse = "https://" + adresse.lstrip("/")
    trouves, vus = [], set()

    def _nb_articles(contenu):
        # Flux valide mais vide (ex. moto-net.com/rss.xml le 10/10/2026)
        return len(_re.findall(rb"<item[\s>]|<entry[\s>]", contenu, _re.IGNORECASE))

    def _verifier(url, timeout=15):
        try:
            finale, contenu = _telecharger_pour_flux(url, timeout=timeout)
        except Exception:
            return False
        titre = _titre_si_flux(contenu)
        if titre and finale not in vus and url not in vus:
            vus.update({finale, url})
            trouves.append((unescape(titre), url, _nb_articles(contenu)))
            return True
        return False

    finale, page = _telecharger_pour_flux(adresse)   # erreur réseau : remontée à l'appelant
    titre = _titre_si_flux(page)
    if titre:
        return [(unescape(titre), adresse, _nb_articles(page))]
    html = page.decode("utf-8", errors="replace")
    for balise in _re.findall(r"<link\b[^>]*>", html, _re.IGNORECASE):
        attr = dict((k.lower(), unescape(v1 or v2)) for k, v1, v2 in
                    _re.findall(r'([a-zA-Z-]+)\s*=\s*(?:"([^"]*)"|\'([^\']*)\')', balise))
        if "alternate" in attr.get("rel", "").lower() and _re.search(
                r"(rss|atom)\+xml|application/xml|text/xml", attr.get("type", ""), _re.IGNORECASE) \
                and attr.get("href"):
            _verifier(urljoin(finale, attr["href"]))
    if not trouves:
        racine = "{0.scheme}://{0.netloc}".format(urlsplit(finale))
        for chemin in _CHEMINS_FLUX_HABITUELS:
            if _verifier(racine + chemin, timeout=8) and len(trouves) >= 3:
                break
    return trouves


class ChercheurFluxRSS(QThread):
    """Recherche de flux en arrière-plan (voir chercher_flux_depuis_url)."""
    resultat = Signal(list, str)   # [(titre, url)], message d'erreur ("" si aucune)

    def __init__(self, adresse):
        super().__init__()
        self.adresse = adresse

    def run(self):
        try:
            self.resultat.emit(chercher_flux_depuis_url(self.adresse), "")
        except Exception as e:
            self.resultat.emit([], f"{type(e).__name__}: {e}")


# ── Flux « page surveillée » : un flux créé par COURRIER pour un site qui
#    n'en propose pas (10/10/2026, demandé) ──────────────────────────────────
# La page (ex. « Actualités ») est relue au plus une fois par
# INTERVALLE_MIN_PAGE_SURVEILLEE_SEC ; chaque nouveau lien de la liste
# d'articles détectée devient un article (titre, résumé et image pris dans
# l'aperçu que l'article fournit lui-même — balises og:), daté du jour où il
# est apparu s'il n'annonce pas sa date. Règles de bon voisinage : jamais de
# page protégée, robots.txt respecté, pas de recopie de l'article entier.
INTERVALLE_MIN_PAGE_SURVEILLEE_SEC = 3600
NB_MAX_APERCUS_PAR_VISITE = 10
_EXTENSIONS_NON_ARTICLE = (".pdf", ".jpg", ".jpeg", ".png", ".gif", ".webp", ".svg", ".zip",
                           ".doc", ".docx", ".xls", ".xlsx", ".mp3", ".mp4", ".ics", ".xml", ".css", ".js")

def robots_autorise(url):
    """Le site autorise-t-il les robots à lire cette page (robots.txt) ?
    Absent ou illisible : autorisé (convention habituelle)."""
    from urllib.robotparser import RobotFileParser
    from urllib.parse import urlsplit
    morceaux = urlsplit(url)
    try:
        _finale, contenu = _telecharger_pour_flux(f"{morceaux.scheme}://{morceaux.netloc}/robots.txt",
                                                  timeout=8, limite=500_000)
    except Exception:
        return True
    analyseur = RobotFileParser()
    analyseur.parse(contenu.decode("utf-8", errors="replace").splitlines())
    return analyseur.can_fetch("COURRIER", url)

def _domaine_principal(netloc):
    hote = netloc.lower().split(":")[0]
    morceaux = hote.split(".")
    return ".".join(morceaux[-2:]) if len(morceaux) >= 2 else hote

def _texte_html(fragment):
    import re as _re
    from html import unescape
    fragment = _re.sub(r"<!--.*?-->", " ", fragment or "", flags=_re.DOTALL)
    return " ".join(unescape(_re.sub(r"<[^>]+>", " ", fragment)).split())

def _attributs_html(balise):
    import re as _re
    from html import unescape
    return {k.lower(): unescape(v1 if v1 is not None and v1 != "" else (v2 or v3 or ""))
            for k, v1, v2, v3 in _re.findall(
                r'([a-zA-Z_:-]+)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s"\'>]+))', balise)}

def _html_sans_habillage(html):
    """Page sans scripts, menus, en-tête, pied de page ni formulaires."""
    import re as _re
    for balise in ("script", "style", "noscript", "nav", "header", "footer", "aside", "form", "svg"):
        html = _re.sub(rf"<{balise}\b.*?</{balise}\s*>", " ", html, flags=_re.IGNORECASE | _re.DOTALL)
    return html

def liens_articles_page(html, url_page):
    """[(url, texte, image)] de tous les liens « candidats » de la page, dans
    l'ordre d'apparition — menus, en-tête, pied de page et formulaires
    retirés, liens vers d'autres sites ou vers des fichiers écartés."""
    import re as _re
    from urllib.parse import urljoin, urlsplit
    html = _html_sans_habillage(html)
    domaine = _domaine_principal(urlsplit(url_page).netloc)
    page_sans_ancre = url_page.split("#")[0].rstrip("/")
    liens, vus = [], {}
    for m in _re.finditer(r"<a\b([^>]*)>(.*?)</a\s*>", html, _re.IGNORECASE | _re.DOTALL):
        attrs = _attributs_html(m.group(1))
        href = (attrs.get("href") or "").strip()
        if not href or href.startswith(("#", "mailto:", "tel:", "javascript:")):
            continue
        absolu = urljoin(url_page, href).split("#")[0]
        morceaux = urlsplit(absolu)
        if morceaux.scheme not in ("http", "https") or _domaine_principal(morceaux.netloc) != domaine:
            continue
        if absolu.rstrip("/") == page_sans_ancre or morceaux.path.lower().endswith(_EXTENSIONS_NON_ARTICLE):
            continue
        interieur = m.group(2)
        texte = _texte_html(interieur) or attrs.get("title", "").strip()
        m_img = _re.search(r"<img\b([^>]*)>", interieur, _re.IGNORECASE)
        image = ""
        if m_img:
            a_img = _attributs_html(m_img.group(1))
            texte = texte or a_img.get("alt", "").strip()
            src = a_img.get("data-src") or a_img.get("src") or ""
            image = urljoin(url_page, src) if src and not src.startswith("data:") else ""
        if absolu in vus:   # même article lié plusieurs fois (image + titre) : on fusionne
            i = vus[absolu]
            u, tx, im = liens[i]
            liens[i] = (u, tx if len(tx) >= len(texte) else texte, im or image)
            continue
        vus[absolu] = len(liens)
        liens.append((absolu, texte, image))
    return liens

def _cle_motif(url):
    """Forme d'un lien, en ignorant ce qui change d'un article à l'autre
    (10/10/2026, corrigé sur motogp.com : un dossier par article,
    « /fr/news/2026/10/10/titre/1174849 ») : les deux premières rubriques
    sont gardées telles quelles (« fr », « news », « actualite »), le reste
    devient « # » (nombre, date) ou « * » (titre…), le dernier élément
    toujours. -> (("fr", "news", "#", "#", "#", "*", "#"), False)."""
    import re as _re
    from urllib.parse import urlsplit
    morceaux = urlsplit(url)
    segments = [s for s in morceaux.path.split("/") if s]
    forme = []
    for i, s in enumerate(segments):
        numerique = bool(_re.fullmatch(r"[\d._-]+", s))
        if i < 2 and i < len(segments) - 1 and not numerique:
            forme.append(s.lower())
        else:
            forme.append("#" if numerique else "*")
    return (tuple(forme), bool(morceaux.query))

def listes_articles_candidates(html, url_page, nb_max=5):
    """[(motif, liens)] des groupes de liens qui ressemblent à une liste
    d'articles, du plus probable au moins probable (10/10/2026 : une page
    d'accueil en mélange souvent plusieurs — vidéos, actualités… —, c'est
    alors à l'utilisateur de choisir)."""
    groupes = {}
    for lien in liens_articles_page(html, url_page):
        groupes.setdefault(_cle_motif(lien[0]), []).append(lien)
    notes = []
    for cle, liens in groupes.items():
        titres = [l for l in liens if len(l[1]) >= 15]
        if len(titres) < 3 or not cle[0]:
            continue
        score = len(titres) * min(sum(len(l[1]) for l in titres) / len(titres), 80) * (len(titres) / len(liens))
        notes.append((score, {"forme": list(cle[0]), "parametres": cle[1]}, liens))
    notes.sort(key=lambda n: n[0], reverse=True)
    return [(motif, liens) for _s, motif, liens in notes[:nb_max]]

def libelle_liste_articles(motif, liens):
    """« Rubrique news — 191 articles — ex. « MotoGP : … » »."""
    rubrique = " / ".join(p for p in motif.get("forme", []) if p not in ("#", "*")) or "racine du site"
    exemple = next((l[1] for l in liens if len(l[1]) >= 15), liens[0][1] if liens else "")
    return f"Rubrique « {rubrique} » — {len(liens)} article(s) — ex. « {exemple[:60]} »"

def detecter_liste_articles(html, url_page):
    """Le groupe de liens qui ressemble le plus à une liste d'articles :
    même forme de lien (voir _cle_motif), au moins 3, et de vrais titres
    (texte long) plutôt que des entrées de menu. Retourne (motif, liens) ou
    (None, [])."""
    groupes = {}
    for lien in liens_articles_page(html, url_page):
        groupes.setdefault(_cle_motif(lien[0]), []).append(lien)
    meilleur, meilleur_score = None, 0.0
    for cle, liens in groupes.items():
        titres = [l for l in liens if len(l[1]) >= 15]
        if len(titres) < 3 or not cle[0]:
            continue
        score = len(titres) * min(sum(len(l[1]) for l in titres) / len(titres), 80) * (len(titres) / len(liens))
        if score > meilleur_score:
            meilleur, meilleur_score = cle, score
    if meilleur is None:
        return None, []
    return {"forme": list(meilleur[0]), "parametres": meilleur[1]}, groupes[meilleur]

def titre_page(html):
    import re as _re
    for motif in (r'<meta[^>]+property=["\']og:site_name["\'][^>]*>', r"<title[^>]*>(.*?)</title>"):
        m = _re.search(motif, html, _re.IGNORECASE | _re.DOTALL)
        if m:
            if m.groups():
                return _texte_html(m.group(1))
            return (_attributs_html(m.group(0)).get("content") or "").strip()
    return ""

def apercu_article(url):
    """Aperçu qu'un article fournit lui-même (balises og: / description) :
    {titre, resume, image, date_brute}. Vide en cas d'échec."""
    import re as _re
    from email.utils import format_datetime
    import datetime as _dt
    try:
        _finale, contenu = _telecharger_pour_flux(url, timeout=10, limite=1_500_000)
    except Exception:
        return {}
    html = contenu.decode("utf-8", errors="replace")
    metas = {}
    for balise in _re.findall(r"<meta\b[^>]*>", html, _re.IGNORECASE):
        a = _attributs_html(balise)
        cle = (a.get("property") or a.get("name") or "").lower()
        if cle and a.get("content") and cle not in metas:
            metas[cle] = a["content"].strip()
    date = metas.get("article:published_time") or metas.get("date") or ""
    if date:
        try:
            date = format_datetime(_dt.datetime.fromisoformat(date.replace("Z", "+00:00")))
        except Exception:
            date = ""
    return {"titre": metas.get("og:title") or metas.get("twitter:title") or "",
            "resume": metas.get("og:description") or metas.get("description") or "",
            "image": metas.get("og:image") or metas.get("twitter:image") or "",
            "date_brute": date}

def articles_page_surveillee(flux, deja_vus):
    """Même résultat que parser_flux_rss pour un flux « page surveillée » :
    les liens de la page qui ont la forme mémorisée (flux["motif"]),
    enrichis de leur aperçu pour les nouveaux (au plus
    NB_MAX_APERCUS_PAR_VISITE par visite)."""
    from email.utils import formatdate
    url = flux.get("url", "")
    motif = flux.get("motif") or {}
    if not robots_autorise(url):
        print(f"[RSS] {flux.get('nom') or url} : le site refuse désormais les robots (robots.txt) — page non lue")
        return {"site_lien": url, "site_description": "", "articles": []}
    _finale, contenu = _telecharger_pour_flux(url)
    html = contenu.decode("utf-8", errors="replace")
    if "forme" not in motif:
        # Flux créé avant la correction du 10/10/2026 : forme recalculée, et
        # nouveau départ (tout ce qui est sur la page marqué « déjà vu »),
        # pour ne pas livrer d'un coup des articles anciens.
        nouveau, _l = detecter_liste_articles(html, url)
        if nouveau:
            flux["motif"] = motif = nouveau
            flux.pop("items_vus", None)
            print(f"[RSS] {flux.get('nom') or url} : forme des articles recalculée ({nouveau})")
    cle_voulue = (tuple(motif.get("forme") or ()), motif.get("parametres"))
    liens = [l for l in liens_articles_page(html, url) if _cle_motif(l[0]) == cle_voulue]
    articles, nb_apercus = [], 0
    for lien, texte, image in liens[:50]:
        article = {"guid": lien, "titre": texte or lien, "lien": lien, "resume": "",
                   "date_brute": formatdate(localtime=True), "image": image, "auteur": ""}
        if lien not in deja_vus and nb_apercus < NB_MAX_APERCUS_PAR_VISITE and "items_vus" in flux:
            nb_apercus += 1
            apercu = apercu_article(lien)
            article["titre"] = apercu.get("titre") or article["titre"]
            article["resume"] = apercu.get("resume") or ""
            article["image"] = apercu.get("image") or article["image"]
            article["date_brute"] = apercu.get("date_brute") or article["date_brute"]
        articles.append(article)
    return {"site_lien": url, "site_description": "", "articles": articles}


def message_erreur_site(erreur):
    """Erreur réseau traduite en clair pour l'utilisateur (10/10/2026)."""
    e = str(erreur)
    if "403" in e or "401" in e:
        return "le site refuse la lecture automatique de ses pages (accès interdit)"
    if "404" in e or "410" in e:
        return "cette page n'existe pas (ou plus) — vérifiez l'adresse"
    if "CERTIFICATE_VERIFY_FAILED" in e or "SSL" in e:
        return "le certificat de sécurité du site est invalide : COURRIER refuse de s'y connecter, comme un navigateur"
    if "getaddrinfo" in e or "Name or service" in e or "11001" in e:
        return "adresse introuvable — vérifiez l'orthographe du site"
    if "timed out" in e or "timeout" in e.lower():
        return "le site ne répond pas (délai dépassé) — réessayez plus tard"
    if "429" in e:
        return "le site limite le nombre de visites — réessayez plus tard"
    return f"site injoignable ({e[:100]})"


class AnalyseurPageRSS(QThread):
    """Analyse d'une page pour y créer un flux (voir detecter_liste_articles)."""
    resultat = Signal(dict)   # {"statut": ok|robots|aucun|erreur, ...}

    def __init__(self, adresse):
        super().__init__()
        self.adresse = adresse

    def run(self):
        import re as _re
        adresse = self.adresse.strip()
        if not _re.match(r"^https?://", adresse, _re.IGNORECASE):
            adresse = "https://" + adresse.lstrip("/")
        try:
            if not robots_autorise(adresse):
                self.resultat.emit({"statut": "robots", "url": adresse})
                return
            finale, contenu = _telecharger_pour_flux(adresse)
            html = contenu.decode("utf-8", errors="replace")
            motif, liens = detecter_liste_articles(html, finale)
            if motif is None:
                # Page d'accueil sans liste d'articles : on essaie sa rubrique
                # d'actualités (lien « News », « Actualités », « Blog »…).
                from urllib.parse import urlsplit as _us
                for lien, _texte, _img in liens_articles_page(html, finale):
                    dernier = [s for s in _us(lien).path.lower().split("/") if s][-1:] or [""]
                    if dernier[0] in ("news", "actualites", "actualite", "actus", "actu", "blog",
                                      "infos", "articles", "presse", "communiques") \
                            and robots_autorise(lien):
                        try:
                            f2, c2 = _telecharger_pour_flux(lien)
                        except Exception:
                            continue
                        html2 = c2.decode("utf-8", errors="replace")
                        m2, l2 = detecter_liste_articles(html2, f2)
                        if m2:
                            finale, html, motif, liens = f2, html2, m2, l2
                            break
            if motif is None:
                # Contenu réel (hors menus) quasi vide : page construite par
                # JavaScript après chargement (ex. fim-moto.com/en/news).
                self.resultat.emit({"statut": "aucun", "url": finale,
                                    "peu_de_texte": len(_texte_html(_html_sans_habillage(html))) < 1500})
                return
            candidates = [{"motif": m, "titres": [l[1] for l in ls], "libelle": libelle_liste_articles(m, ls)}
                          for m, ls in listes_articles_candidates(html, finale)] or \
                         [{"motif": motif, "titres": [l[1] for l in liens],
                           "libelle": libelle_liste_articles(motif, liens)}]
            self.resultat.emit({"statut": "ok", "url": finale, "motif": candidates[0]["motif"],
                                "titres": candidates[0]["titres"], "candidates": candidates,
                                "nom": titre_page(html)})
        except Exception as e:
            self.resultat.emit({"statut": "erreur", "url": adresse, "erreur": f"{type(e).__name__}: {e}"})


class VerificateurRSS(QThread):
    """Vérifie tous les flux RSS/Atom abonnés en une passe et dépose chaque
    nouvel article directement dans l'INBOX du compte associé, via IMAP
    APPEND — comme un vrai mail reçu. À la toute première vérification d'un
    flux fraîchement ajouté, rien n'est déposé (tout l'historique existant
    est simplement marqué "déjà vu") pour ne pas déverser d'un coup tout le
    passé du flux dans la boîte de réception — seuls les articles publiés
    APRÈS l'abonnement sont livrés, comme on s'y attend d'un abonnement."""
    resultat = Signal(list)  # adresses des comptes ayant reçu du nouveau contenu

    def __init__(self, forcer_programmes=False):
        super().__init__()
        # True pour "Vérifier maintenant" : les programmes de mise à jour
        # des flux sont lancés sans attendre la fin de leur période.
        self.forcer_programmes = forcer_programmes

    def run(self):
        donnees = charger_abonnements_rss()
        comptes_touches = set()
        modifie = False
        for flux in donnees.get("flux", []):
            try:
                if self._verifier_un_flux(flux):
                    comptes_touches.add(flux.get("compte", ""))
                modifie = True
            except Exception as e:
                print(f"[RSS] Erreur lors de la vérification de {flux.get('url','?')} : {e}")
        if modifie:
            sauvegarder_abonnements_rss(donnees)
        self.resultat.emit(list(comptes_touches))

    def _verifier_un_flux(self, flux):
        import urllib.request, urllib.error
        url = flux.get("url", "")
        compte_adresse = flux.get("compte", "")
        if not url or not compte_adresse:
            return False
        compte = next((c for c in COMPTES if c.get("adresse") == compte_adresse), None)
        if not compte:
            return False
        if flux.get("type") == "page":
            # Flux créé par COURRIER (voir articles_page_surveillee) : au plus
            # une visite par heure, même si la vérification RSS est plus
            # fréquente — sauf « Vérifier maintenant ».
            import time as _t_page
            if not self.forcer_programmes and _t_page.time() - float(
                    flux.get("page_derniere_visite", 0) or 0) < INTERVALLE_MIN_PAGE_SURVEILLEE_SEC:
                return False
            flux["page_derniere_visite"] = _t_page.time()
            try:
                resultat_parse = articles_page_surveillee(flux, set(flux.get("items_vus", [])))
            except Exception as e:
                print(f"[RSS] Échec de la lecture de la page {url} : {e}")
                return False
            return self._traiter_articles(compte, flux, resultat_parse)

        # Requêtes conditionnelles ETag/Last-Modified (19/08/2026, demandé
        # par l'utilisateur après avoir vérifié comment Blogtrottr procède
        # réellement : ETag/Last-Modified + respect du <ttl> du flux +
        # WebSub quand disponible). Le serveur peut répondre "304 Not
        # Modified" sans renvoyer le contenu du tout si rien n'a changé
        # depuis la dernière vérification — nettement plus léger pour le
        # flux, en particulier à 10 minutes d'intervalle. Les valeurs
        # reçues sont mémorisées sur le flux lui-même, renvoyées telles
        # quelles à la vérification suivante.
        entetes = {"User-Agent": "Mozilla/5.0 (compatible; COURRIER RSS)"}
        if flux.get("etag"):
            entetes["If-None-Match"] = flux["etag"]
        if flux.get("last_modified"):
            entetes["If-Modified-Since"] = flux["last_modified"]

        try:
            requete = urllib.request.Request(url, headers=entetes)
            with urllib.request.urlopen(requete, timeout=15, context=CONTEXTE_SSL) as reponse:
                contenu = reponse.read()
                if reponse.headers.get("ETag"):
                    flux["etag"] = reponse.headers.get("ETag")
                if reponse.headers.get("Last-Modified"):
                    flux["last_modified"] = reponse.headers.get("Last-Modified")
        except urllib.error.HTTPError as e:
            if e.code == 304:
                # Rien de nouveau depuis la dernière vérification — le cas
                # normal et attendu la plupart du temps, pas une erreur.
                return False
            print(f"[RSS] Échec du téléchargement de {url} : {e}")
            return False
        except Exception as e:
            print(f"[RSS] Échec du téléchargement de {url} : {e}")
            return False

        return self._traiter_articles(compte, flux, parser_flux_rss(contenu))

    def _traiter_articles(self, compte, flux, resultat_parse):
        """Suite commune aux vrais flux et aux pages surveillées : repérage
        des nouveaux articles et dépôt dans la boîte du compte."""
        url = flux.get("url", "")
        articles = resultat_parse["articles"]
        if not articles:
            return False
        # Lien + description du site (18/08-19/08/2026, rendu façon
        # Blogtrottr — le nom du flux, affiché en tête de chaque mail, y
        # renvoie quand le flux le fournit ; la description apparaît
        # juste dessous, comme le sous-titre "Retrouvez toute l'actualité
        # du MotoGP" observé chez Blogtrottr). Mémorisés sur le flux
        # lui-même, pas besoin de les retélécharger à chaque article.
        if resultat_parse.get("site_lien"):
            flux["site_lien"] = resultat_parse["site_lien"]
        if resultat_parse.get("site_description"):
            flux["site_description"] = resultat_parse["site_description"]

        items_vus = set(flux.get("items_vus", []))
        premiere_verification = "items_vus" not in flux
        nouveaux = [a for a in articles if a["guid"] not in items_vus]

        if premiere_verification:
            flux["items_vus"] = [a["guid"] for a in articles][:NB_MAX_ITEMS_VUS_PAR_FLUX]
            return False

        # Coupe-circuit anti-avalanche (20/08/2026, suite à l'incident KTM
        # récurrent malgré la fenêtre items_vus déjà élargie à 5000) : un
        # flux peut, pour une raison propre à son serveur (bug, cache,
        # reset d'ID, réémission de tout ou partie de son historique...),
        # se remettre soudain à "redécouvrir" des centaines voire des
        # milliers d'articles comme nouveaux en une seule vérification. Un
        # vrai flux d'actualité ne produit jamais ça en 10 minutes : au-delà
        # du seuil, on ne dépose que les quelques articles les plus récents
        # et on marque TOUT le reste comme déjà vu sans le déposer, pour
        # stopper net toute avalanche future — sur ce flux comme sur
        # n'importe quel autre parmi les abonnements.
        SEUIL_ANOMALIE_NOUVEAUX_PAR_FLUX = 30
        NB_DEPOSES_SI_ANOMALIE = 3
        anomalie = len(nouveaux) > SEUIL_ANOMALIE_NOUVEAUX_PAR_FLUX
        if anomalie:
            nouveaux_tries = sorted(
                nouveaux,
                key=lambda a: _parser_date_flux(a.get("date_brute", "")) or datetime.datetime.min,
                reverse=True,
            )
            print(f"[RSS] ANOMALIE sur '{flux.get('nom') or url}' : {len(nouveaux)} articles "
                  f"'nouveaux' en une seule vérification (seuil {SEUIL_ANOMALIE_NOUVEAUX_PAR_FLUX}) "
                  f"— probable réémission par le serveur, pas un vrai flot d'actualité. Seuls les "
                  f"{NB_DEPOSES_SI_ANOMALIE} plus récents sont déposés, le reste est marqué comme "
                  f"déjà vu sans dépôt.")
            nouveaux = nouveaux_tries[:NB_DEPOSES_SI_ANOMALIE]

        for article in nouveaux:
            try:
                self._deposer_article(compte, flux, article)
            except Exception as e:
                print(f"[RSS] Échec du dépôt de l'article '{article.get('titre','?')}' : {e}")

        if anomalie:
            # Tous les articles de cette réponse (déposés ou écartés comme
            # anomalie) sont marqués vus, pas seulement ceux réellement
            # déposés, pour ne pas retenter les articles écartés à chaque
            # prochaine vérification.
            deja_vus = list(items_vus) + [a["guid"] for a in articles]
        else:
            deja_vus = list(items_vus) + [a["guid"] for a in nouveaux]
        flux["items_vus"] = deja_vus[-NB_MAX_ITEMS_VUS_PAR_FLUX:]
        return bool(nouveaux)

    def _deposer_article(self, compte, flux, article):
        """Construit le mail déposé pour un article (18-19/08/2026, rendu
        façon Blogtrottr à la demande de l'utilisateur — comparaison
        directe faite avec un vrai mail Blogtrottr par l'utilisateur le
        19/08 : nom du site en tête (avec sa description en sous-titre si
        le flux la fournit), titre cliquable, ligne auteur/date, visuel de
        l'article s'il y en a un, contenu (complet si le flux le fournit
        via <content:encoded>/Atom <content>, résumé sinon — voir
        parser_flux_rss), puis lien vers l'article complet en dessous."""
        from email.mime.multipart import MIMEMultipart
        from email.mime.text import MIMEText
        from email.utils import make_msgid, formatdate
        import re as _re_html, time as _time_rss, html as _html_mod

        nom_flux = flux.get("nom") or "RSS"
        lien_site = flux.get("site_lien") or ""
        description_site = flux.get("site_description") or ""
        titre = article.get("titre") or "(sans titre)"
        lien = article.get("lien") or ""
        resume = article.get("resume") or ""
        image = article.get("image") or ""
        auteur = article.get("auteur") or ""

        msg = MIMEMultipart("mixed")
        # Adresse d'expéditeur synthétique dérivée du nom du flux — aucun
        # mail n'est réellement envoyé à qui que ce soit, ce champ ne sert
        # qu'à un affichage lisible dans la liste des mails de COURRIER.
        expediteur_safe = "".join(c if c.isalnum() else "-" for c in nom_flux.lower()).strip("-") or "flux"
        msg["From"] = f"{nom_flux} <{expediteur_safe}@rss.local>"
        msg["To"] = compte["adresse"]
        msg["Subject"] = titre
        msg["Message-ID"] = make_msgid(domain="rss.local")

        date_article = _parser_date_flux(article.get("date_brute", ""))
        msg["Date"] = formatdate(
            timeval=_time_rss.mktime(date_article.timetuple()) if date_article else _time_rss.time(),
            localtime=True
        )

        titre_echappe = _html_mod.escape(titre)
        nom_flux_echappe = _html_mod.escape(nom_flux)
        en_tete_site = (
            f'<a href="{lien_site}" style="color:#A52A2A; text-decoration:none;">{nom_flux_echappe}</a>'
            if lien_site else nom_flux_echappe
        )
        sous_titre_site_html = (
            f'<div style="font-size:13px; color:#888; margin-top:2px; margin-bottom:10px;">'
            f'{_html_mod.escape(description_site)}</div>'
            if description_site else ""
        )
        # Titre cliquable (19/08/2026, demandé après comparaison avec
        # Blogtrottr, qui affiche le titre comme un lien souligné).
        titre_html = (
            f'<a href="{lien}" style="color:#111; text-decoration:underline;">{titre_echappe}</a>'
            if lien else titre_echappe
        )
        # Ligne auteur/date (19/08/2026, demandé — façon Blogtrottr
        # "Aug 18th 2026, 16:00 by André Lecondé").
        morceaux_byline = []
        if date_article:
            morceaux_byline.append(date_article.strftime("%d/%m/%Y à %H:%M"))
        if auteur:
            morceaux_byline.append(f"par {_html_mod.escape(auteur)}")
        byline_html = (
            f'<div style="font-size:13px; color:#888; margin-bottom:14px;">{" — ".join(morceaux_byline)}</div>'
            if morceaux_byline else ""
        )
        image_html = (
            f'<a href="{lien}" style="text-decoration:none;">'
            f'<img src="{image}" style="display:block; width:100%; max-width:640px; '
            f'border-radius:6px; margin:16px 0;"></a>'
            if image else ""
        )
        lien_html = (
            f'<p style="margin-top:22px;"><a href="{lien}" '
            f'style="font-size:18px; color:#A52A2A; font-weight:bold; text-decoration:none;">'
            f'Lire l\'article complet →</a></p>'
            if lien else ""
        )
        # Résumé/contenu "assaini" avant insertion (18/08/2026, bug corrigé
        # après capture d'écran d'un test réel — le HTML brut du flux,
        # potentiellement mal formé, cassait toute la mise en page
        # environnante). Repris le 19/08/2026 pour PRÉSERVER les coupures
        # de paragraphe (perdues jusqu'ici, tout le texte finissait sur
        # une seule ligne compacte) : les balises de bloc (</p>, <br>,
        # </div>, </li>, </h1-6>) sont d'abord converties en "double saut
        # de ligne" AVANT de retirer le reste des balises, préservant la
        # structure en paragraphes façon Blogtrottr — au prix, comme avant,
        # de la mise en forme (gras/italique/liens) À L'INTÉRIEUR du texte
        # lui-même, jamais de la mise en page globale du mail (elle, reste
        # entièrement sous notre contrôle donc jamais cassée par un flux
        # mal formé, quel que soit son contenu).
        resume_avec_sauts = _re_html.sub(
            r'</(p|div|li|h[1-6])>|<br\s*/?>', '\n\n', resume, flags=_re_html.IGNORECASE
        )
        resume_texte = _re_html.sub(r'<[^>]+>', '', resume_avec_sauts)
        resume_texte = _html_mod.unescape(resume_texte)
        # Espaces/tabulations compactés SANS toucher aux sauts de ligne,
        # puis paragraphes vides (3+ sauts consécutifs) ramenés à 2.
        resume_texte = _re_html.sub(r'[ \t]+', ' ', resume_texte)
        resume_texte = _re_html.sub(r'\n{3,}', '\n\n', resume_texte).strip()
        paragraphes = [p.strip() for p in resume_texte.split("\n\n") if p.strip()]
        resume_html_sur = "".join(
            f'<p style="margin:0 0 14px 0;">{_html_mod.escape(p)}</p>' for p in paragraphes
        )
        corps_html = (
            '<div style="font-family:Verdana, Arial, sans-serif; max-width:680px; margin:0 auto;">'
            f'<div style="font-size:24px; font-weight:bold;">{en_tete_site}</div>'
            f'{sous_titre_site_html}'
            f'<div style="font-size:21px; font-weight:bold; line-height:1.3; color:#111; '
            f'margin-bottom:4px;">{titre_html}</div>'
            f'{byline_html}'
            f'{image_html}'
            f'<div style="font-size:16px; color:#333; line-height:1.6;">{resume_html_sur}</div>'
            f'{lien_html}'
            '</div>'
        )
        corps_texte = (
            f"{nom_flux}\n{titre}\n\n"
            + resume_texte
            + (f"\n\n{lien}" if lien else "")
        )

        alt = MIMEMultipart("alternative")
        alt.attach(MIMEText(corps_texte or " ", "plain", "utf-8"))
        alt.attach(MIMEText(corps_html, "html", "utf-8"))
        msg.attach(alt)

        conn = connexion_imap(compte)
        try:
            conn = _authentifier_connexion_imap(conn, compte)
            conn.append('"INBOX"', "", imaplib.Time2Internaldate(_time_rss.time()), msg.as_bytes())
        finally:
            fermer_connexion_imap(conn)

class RecuperateurAnciensArticles(VerificateurRSS):
    """Récupère manuellement les N derniers articles déjà présents dans un
    flux (18/08/2026, demandé par l'utilisateur — pratique pour tester sans
    attendre l'arrivée d'un nouvel article, comme le proposent la plupart
    des gestionnaires de flux au moment de l'abonnement). Hérite de
    VerificateurRSS pour réutiliser _deposer_article tel quel — seule la
    logique de sélection change : contrairement à la vérification
    périodique normale, la protection "1ère vérification = rien déposer"
    est volontairement IGNORÉE ici, c'est justement le but recherché. Les
    articles récupérés sont ensuite marqués "déjà vus" comme les autres,
    pour que la vérification périodique normale ne les redépose pas."""
    resultat = Signal(bool, str)  # succès, message (erreur ou résumé)
    # Avancement (28/09/2026, demandé — aucune indication pendant une longue
    # récupération) : étape en cours, articles déposés, total (0 = indéterminé).
    progression = Signal(str, int, int)

    def __init__(self, id_flux, nombre):
        super().__init__()
        self.id_flux = id_flux
        self.nombre = nombre

    def run(self):
        donnees = charger_abonnements_rss()
        flux = next((f for f in donnees.get("flux", []) if f.get("id") == self.id_flux), None)
        if not flux:
            self.resultat.emit(False, "Flux introuvable.")
            return
        compte = next((c for c in COMPTES if c.get("adresse") == flux.get("compte")), None)
        if not compte:
            self.resultat.emit(False, "Compte introuvable.")
            return
        if flux.get("programme"):
            self.progression.emit("Lancement du programme de mise à jour du flux...", 0, 0)

        import urllib.request
        url = flux.get("url", "")
        self.progression.emit("Téléchargement du flux...", 0, 0)
        try:
            requete = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (compatible; COURRIER RSS)"})
            with urllib.request.urlopen(requete, timeout=15, context=CONTEXTE_SSL) as reponse:
                contenu = reponse.read()
        except Exception as e:
            self.resultat.emit(False, f"Échec du téléchargement : {e}")
            return

        resultat_parse = parser_flux_rss(contenu)
        articles = resultat_parse["articles"]
        if not articles:
            self.resultat.emit(False, "Aucun article trouvé dans ce flux.")
            return
        if resultat_parse.get("site_lien"):
            flux["site_lien"] = resultat_parse["site_lien"]

        a_recuperer = articles[:self.nombre]
        nb_deposes = 0
        total = len(a_recuperer)
        for i, article in enumerate(a_recuperer):
            self.progression.emit(f"Dépôt de l'article {i + 1} sur {total}...", i, total)
            try:
                self._deposer_article(compte, flux, article)
                nb_deposes += 1
            except Exception as e:
                print(f"[RSS] Échec du dépôt (récupération manuelle) de "
                      f"'{article.get('titre','?')}' : {e}")
        self.progression.emit("Enregistrement...", total, total)

        # TOUS les articles vus par ce téléchargement sont marqués "vus" —
        # pas seulement ceux effectivement récupérés — pour que la
        # vérification périodique normale ne redépose pas ensuite ceux
        # restés au-delà du nombre demandé.
        items_vus = set(flux.get("items_vus", []))
        items_vus |= {a["guid"] for a in articles}
        flux["items_vus"] = list(items_vus)[-NB_MAX_ITEMS_VUS_PAR_FLUX:]
        sauvegarder_abonnements_rss(donnees)
        self.resultat.emit(True, f"{nb_deposes} article(s) récupéré(s) sur {len(a_recuperer)} demandé(s).")

# --- Bouton TÉL : écran du téléphone Android (07/10/2026) ---
# Repris du bouton téléphone de navigateur.py : connexion par adb (déjà
# relié en USB/Wi-Fi, sinon recherche mDNS du débogage sans fil puis
# "adb connect"), puis ouverture de l'écran dans une fenêtre scrcpy.
# scrcpy 5.0 est embarqué dans DOSSIER_APP\scrcpy (07/10/2026, pour la
# build : copié depuis ressources\scrcpy au premier lancement). Garder la
# même version que celle du navigateur : deux adb de versions différentes
# se tuent mutuellement leur serveur. Si la fenêtre "Téléphone" est déjà
# ouverte (par COURRIER ou par le navigateur), elle est ramenée devant.
DOSSIER_SCRCPY = os.path.join(DOSSIER_APP, "scrcpy")
CHEMIN_SCRCPY = os.path.join(DOSSIER_SCRCPY, "scrcpy.exe")
CHEMINS_ADB = (
    os.path.join(DOSSIER_SCRCPY, "adb.exe"),
)
INFOBULLE_BOUTON_TEL = "Afficher l'écran du téléphone (Wi-Fi ou USB)"
TITRE_FENETRE_TELEPHONE = "Téléphone"
CHEMIN_JOURNAL_SCRCPY = os.path.join(DOSSIER_APP, "journal_scrcpy.log")
_processus_scrcpy = None


def chemin_adb():
    for chemin in CHEMINS_ADB:
        if os.path.isfile(chemin):
            return chemin
    return shutil.which("adb")


def _requete_mdns(nom):
    return b"".join(bytes([len(p)]) + p.encode() for p in nom.split(".")) + b"\0"


def _lire_nom_mdns(donnees, i):
    """Nom DNS à la position i (pointeurs de compression compris) -> (nom, position suivante)."""
    morceaux, retour = [], None
    for _ in range(64):  # garde-fou contre une boucle de pointeurs malformée
        longueur = donnees[i]
        if longueur == 0:
            i += 1
            break
        if longueur & 0xC0 == 0xC0:
            if retour is None:
                retour = i + 2
            i = ((longueur & 0x3F) << 8) | donnees[i + 1]
            continue
        morceaux.append(donnees[i + 1:i + 1 + longueur].decode("utf-8", "replace"))
        i += 1 + longueur
    return ".".join(morceaux), (retour if retour is not None else i)


def chercher_telephone_wifi(delai=3.0):
    """Adresse "ip:port" annoncée en mDNS (_adb-tls-connect._tcp) par un
    téléphone dont le débogage sans fil est actif, ou None. Bloquant
    jusqu'à `delai` secondes : à appeler hors du fil de l'interface."""
    import socket, struct, time
    service = "_adb-tls-connect._tcp.local"
    question = (struct.pack(">HHHHHH", 0, 0, 1, 0, 0, 0) + _requete_mdns(service)
                + struct.pack(">HH", 12, 0x8001))
    prise = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPPROTO_UDP)
    try:
        prise.bind(("", 0))
        prise.settimeout(0.4)
        prise.setsockopt(socket.IPPROTO_IP, socket.IP_MULTICAST_TTL, 255)
        fin = time.monotonic() + delai
        envois = 0
        while time.monotonic() < fin:
            if envois < 3:
                prise.sendto(question, ("224.0.0.251", 5353))
                envois += 1
            try:
                donnees, (ip_source, _) = prise.recvfrom(9000)
            except socket.timeout:
                continue
            try:
                _, _, nb_q, nb_r, nb_a, nb_s = struct.unpack(">HHHHHH", donnees[:12])
                i = 12
                for _ in range(nb_q):
                    _, i = _lire_nom_mdns(donnees, i)
                    i += 4
                for _ in range(nb_r + nb_a + nb_s):
                    nom, i = _lire_nom_mdns(donnees, i)
                    type_rr, _, _, longueur = struct.unpack(">HHIH", donnees[i:i + 10])
                    i += 10
                    if type_rr == 33 and service in nom:  # SRV : le port
                        port = struct.unpack(">HHH", donnees[i:i + 6])[2]
                        return f"{ip_source}:{port}"
                    i += longueur
            except (IndexError, struct.error):
                continue  # paquet d'un autre appareil, mal formé : ignoré
    except OSError as exc:
        print(f"[TELEPHONE] recherche Wi-Fi impossible : {exc}")
    finally:
        prise.close()
    return None


class _RelaisTelephone(QObject):
    """Ramène dans le fil de l'interface le résultat de chercher_telephone_wifi."""
    fini = Signal(object)


def connecter_telephone(parent=None, apres=None, si_echec=None):
    """S'assure qu'un téléphone est joignable par adb, puis appelle
    apres(numero_de_serie). Asynchrone (QProcess + thread) : l'interface
    ne gèle pas pendant la recherche. En cas d'échec, une boîte de
    dialogue explique quoi vérifier."""
    from PySide6.QtCore import QProcess
    from PySide6.QtWidgets import QMessageBox
    adb = chemin_adb()

    def _echec(message):
        print(f"[TELEPHONE] échec : {message}")
        if si_echec:
            si_echec()
        QMessageBox.warning(parent, "Téléphone", message)

    if not adb:
        _echec("adb.exe introuvable : impossible de joindre le téléphone.\n\n"
               "Il se trouve normalement dans :\n" + CHEMINS_ADB[0])
        return

    def _lancer(arguments, suite):
        processus = QProcess(parent)

        def _fini(code, _statut):
            sortie = bytes(processus.readAllStandardOutput()
                           + processus.readAllStandardError()).decode("utf-8", "replace")
            processus.deleteLater()
            suite(code, sortie)

        def _erreur(e):
            if e == QProcess.FailedToStart:
                _echec(f"adb n'a pas pu être lancé ({e}).")

        processus.finished.connect(_fini)
        processus.errorOccurred.connect(_erreur)
        processus.start(adb, arguments)

    def _apres_connect(code, sortie, adresse):
        if "connected to" in sortie and "cannot" not in sortie:
            print(f"[TELEPHONE] connecté en Wi-Fi : {adresse}")
            if apres:
                apres(adresse)
        else:
            _echec(f"Le téléphone a été trouvé ({adresse}) mais refuse la connexion.\n\n"
                   f"{sortie.strip()}\n\nSi c'est un nouveau téléphone ou si l'appairage a été "
                   f"effacé, il faut l'appairer à nouveau (une seule fois, avec QtScrcpy ou "
                   f"« adb pair »).")

    def _apres_recherche(adresse):
        if not adresse:
            _echec("Aucun téléphone trouvé.\n\nVérifiez que :\n"
                   "  • le téléphone est sur le même Wi-Fi que l'ordinateur ;\n"
                   "  • « Débogage sans fil » est activé (Options pour les développeurs) ;\n"
                   "  • le téléphone est déverrouillé.\n\n"
                   "Ou branchez-le simplement en USB.")
            return
        _lancer(["connect", adresse], lambda c, s: _apres_connect(c, s, adresse))

    def _apres_liste(code, sortie):
        appareils = [l.split()[0] for l in sortie.splitlines()[1:]
                     if l.strip().endswith("device")]
        if appareils:
            if apres:
                apres(appareils[0])
            return
        print("[TELEPHONE] aucun téléphone relié, recherche en Wi-Fi…")
        relais = _RelaisTelephone(parent)

        def _resultat(adresse):
            relais.deleteLater()
            _apres_recherche(adresse)

        relais.fini.connect(_resultat)
        _threading.Thread(target=lambda: relais.fini.emit(chercher_telephone_wifi()),
                          daemon=True).start()

    _lancer(["devices"], _apres_liste)


def _ramener_fenetre_telephone(serie):
    """Ramène devant la fenêtre scrcpy "Téléphone" si elle existe déjà
    (ouverte par COURRIER ou par le navigateur). Renvoie True si trouvée."""
    import ctypes, subprocess
    fenetre = ctypes.windll.user32.FindWindowW(None, TITRE_FENETRE_TELEPHONE)
    if not fenetre:
        return False
    ctypes.windll.user32.ShowWindow(fenetre, 9)  # SW_RESTORE
    ctypes.windll.user32.SetForegroundWindow(fenetre)
    # Téléphone passé en veille depuis l'ouverture : on le réveille.
    if serie:
        subprocess.Popen([chemin_adb(), "-s", serie, "shell", "input", "keyevent", "KEYCODE_WAKEUP"],
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         stdin=subprocess.DEVNULL, creationflags=subprocess.CREATE_NO_WINDOW)
    return True


def afficher_ecran_telephone(serie, parent=None):
    """Ouvre l'écran du téléphone `serie` dans une fenêtre scrcpy (mêmes
    réglages que le navigateur : 2 Mbps, 1080, sans reverse connection,
    sans le son), ou ramène au premier plan celle déjà ouverte."""
    import subprocess
    from PySide6.QtWidgets import QMessageBox
    global _processus_scrcpy
    if _ramener_fenetre_telephone(serie):
        return
    if not os.path.isfile(CHEMIN_SCRCPY):
        QMessageBox.warning(parent, "Téléphone", f"scrcpy introuvable :\n{CHEMIN_SCRCPY}")
        return
    print(f"[TELEPHONE] ouverture de l'écran de {serie}")
    journal = open(CHEMIN_JOURNAL_SCRCPY, "w", encoding="utf-8", errors="replace")
    _processus_scrcpy = subprocess.Popen(
        [CHEMIN_SCRCPY, f"--serial={serie}", f"--window-title={TITRE_FENETRE_TELEPHONE}",
         "--video-bit-rate=2M", "--max-size=1080", "--force-adb-forward", "--no-audio"],
        cwd=DOSSIER_SCRCPY, stdout=journal, stderr=subprocess.STDOUT,
        # Icône du téléphone orange dans la barre des tâches (comme le navigateur)
        env=dict(os.environ, SCRCPY_ICON_DIR=os.path.join(DOSSIER_SCRCPY, "icone_telephone")),
        stdin=subprocess.DEVNULL, creationflags=subprocess.CREATE_NO_WINDOW)
    journal.close()  # le processus garde sa propre copie du descripteur
    processus = _processus_scrcpy

    def _verifier():
        # scrcpy mort dans les premières secondes = échec : on montre la
        # fin de son journal plutôt que de ne rien afficher du tout.
        if processus.poll() is not None:
            try:
                with open(CHEMIN_JOURNAL_SCRCPY, encoding="utf-8", errors="replace") as f:
                    fin = "".join(f.readlines()[-8:]).strip()
            except OSError:
                fin = ""
            print(f"[TELEPHONE] scrcpy s'est arrêté : {fin}")
            QMessageBox.warning(parent, "Téléphone",
                                "L'écran du téléphone n'a pas pu s'ouvrir.\n\n"
                                "Si QtScrcpy est ouvert, fermez-le puis recommencez.\n\n" + fin)

    QTimer.singleShot(5000, _verifier)


# --- SMS : envoi automatique par le téléphone relié (07/10/2026) ---
# Pas de passerelle ni d'appli à installer sur le téléphone : pour chaque
# destinataire, adb ouvre l'appli SMS du téléphone sur le numéro avec le
# texte déjà tapé (intent SENDTO + sms_body), relit l'écran (uiautomator
# dump) pour y trouver le bouton "Envoyer", simule l'appui dessus, puis
# vérifie que le champ de saisie s'est vidé (= SMS parti). Testé sur
# Samsung Galaxy S20+ / Android 13 / Messages Samsung (bouton
# ...:id/send_button, description "Envoyer"). Le téléphone doit rester
# allumé et déverrouillé : sinon l'envoi se met en pause tout seul.
# Intervalle minimum imposé entre deux SMS (choix de l'auteur) : les
# opérateurs bloquent temporairement la ligne en cas de rafale.
INTERVALLE_MIN_SMS = 20
FICHIER_PROGRESSION_SMS = os.path.join(DOSSIER_APP, "sms_progression.json")
# Caractères de l'alphabet GSM 7 bits : 160 caractères par SMS (153 par
# morceau s'il est long). Un seul caractère hors de cette liste (emoji,
# lettre accentuée autre que é è ù ì ò à...) fait passer tout le message
# en Unicode : 70 caractères par SMS (67 par morceau).
_ALPHABET_GSM = set(
    "@£$¥èéùìòÇ\nØø\rÅåΔ_ΦΓΛΩΠΨΣΘΞÆæßÉ !\"#¤%&'()*+,-./0123456789:;<=>?"
    "¡ABCDEFGHIJKLMNOPQRSTUVWXYZÄÖÑÜ§¿abcdefghijklmnopqrstuvwxyzäöñüà"
    "^{}\\[~]|€"
)


def normaliser_numero_sms(texte):
    """Numéro utilisable pour un SMS (chiffres, + initial éventuel) ou
    None. Accepte espaces, points, tirets, parenthèses ("+33 (0)6 12 34
    56 78", "06.12.34.56.78") ; 4 à 15 chiffres (numéros courts compris)."""
    texte = (texte or "").strip().replace(" ", " ").replace("(0)", "")
    if not texte or not re.fullmatch(r"\+?[\d\s.\-()/]+", texte):
        return None
    chiffres = re.sub(r"\D", "", texte)
    if not 4 <= len(chiffres) <= 15:
        return None
    # Numéro français (commence par 0, pas 00) : 10 chiffres obligatoires
    # (08/10/2026 : "0613" était accepté comme un numéro court)
    if not texte.startswith("+") and chiffres.startswith("0") and not chiffres.startswith("00") \
            and len(chiffres) != 10:
        return None
    return ("+" if texte.startswith("+") else "") + chiffres


# Caractères typographiques remplacés avant l'envoi (07/10/2026) : absents
# de l'alphabet GSM, un seul d'entre eux faisait passer tout le message en
# Unicode (70 caractères par SMS au lieu de 160). Les lettres accentuées
# (â, ê, ô, ç...) ne sont PAS touchées : on ne change pas l'orthographe.
_REMPLACEMENTS_SMS = str.maketrans({
    "’": "'", "‘": "'", "‚": "'", "‛": "'", "′": "'",
    "“": '"', "”": '"', "„": '"', "‟": '"', "″": '"',
    "«": '"', "»": '"',
    "…": "...",
    "–": "-", "—": "-", "‒": "-", "−": "-", "‐": "-", "‑": "-",
    "œ": "oe", "Œ": "OE",
    " ": " ", " ": " ", " ": " ", " ": " ", " ": " ",
})


def normaliser_texte_sms(texte):
    """Texte prêt à envoyer : caractères typographiques remplacés par leur
    équivalent de l'alphabet SMS standard (voir _REMPLACEMENTS_SMS)."""
    return (texte or "").translate(_REMPLACEMENTS_SMS)


def formater_numero_telephone(texte):
    """Écriture uniforme d'un numéro (08/10/2026) : français par paires
    ("0612345678", "06.12.34.56.78", "06-12-34-56-78" -> "06 12 34 56 78" ;
    "+33612345678" ou "0033..." -> "+33 6 12 34 56 78"). Numéros courts,
    étrangers ou non reconnus : laissés tels quels."""
    texte = (texte or "").strip()
    numero = normaliser_numero_sms(texte)
    if not numero:
        return texte
    m = re.fullmatch(r"0(\d)(\d{8})", numero)
    if m:
        return "0" + m.group(1) + " " + " ".join(re.findall(r"\d\d", m.group(2)))
    m = re.fullmatch(r"(?:\+33|0033)(\d)(\d{8})", numero)
    if m:
        return "+33 " + m.group(1) + " " + " ".join(re.findall(r"\d\d", m.group(2)))
    return texte


def _cle_numero(numero):
    """Chiffres d'un numéro, +33/0033 ramenés à 0 : "+33 6 13..." et
    "06 13..." donnent la même clé."""
    chiffres = re.sub(r"\D", "", numero or "")
    if (numero or "").strip().startswith("+33") or chiffres.startswith("0033"):
        chiffres = "0" + chiffres[2:] if chiffres.startswith("33") else "0" + chiffres[4:]
    return chiffres


def completer_noms_depuis_carnet(destinataires):
    """Numéros tapés sans nom (08/10/2026) : le nom du contact du carnet
    qui a ce portable, pour le journal et pour {nom}."""
    if all(nom for nom, _ in destinataires):
        return destinataires
    noms = {}
    for c in charger_carnet().get("contacts", []):
        cle = _cle_numero(c.get("portable", ""))
        if cle and c.get("nom", "").strip():
            noms.setdefault(cle, c["nom"].strip())
    return [(nom or noms.get(_cle_numero(numero), ""), numero) for nom, numero in destinataires]


def formater_destinataires_sms(texte):
    """Remet en forme les numéros d'une ligne À de la fenêtre SMS, sans
    toucher au reste (noms, séparateurs, saisies invalides)."""
    morceaux = re.split(r"([;,\n])", texte or "")
    for i, p in enumerate(morceaux):
        if i % 2:
            continue  # séparateur
        m = re.fullmatch(r"(\s*)(.*?)(\s*)<([^>]*)>(\s*)", p)
        if m:
            morceaux[i] = f"{m.group(1)}{m.group(2)}{m.group(3)}<{formater_numero_telephone(m.group(4))}>{m.group(5)}"
        elif normaliser_numero_sms(p.strip()):
            espace = p[:len(p) - len(p.lstrip())]
            morceaux[i] = espace + formater_numero_telephone(p) + p[len(p.rstrip()):]
    return "".join(morceaux)


def compter_sms(texte):
    """(nombre de caractères, nombre de SMS, caractères hors alphabet SMS
    standard) pour ce texte, une fois normalisé comme à l'envoi."""
    texte = normaliser_texte_sms(texte)
    n = len(texte)
    hors_gsm = sorted({c for c in texte if c not in _ALPHABET_GSM})
    if not hors_gsm:
        return n, (1 if n <= 160 else -(-n // 153)), []
    return n, (1 if n <= 70 else -(-n // 67)), hors_gsm


def est_fixe_francais(numero):
    """True pour un numéro français qui n'est pas un portable (01 à 05,
    08, 09 ; +33 de même) : il ne peut pas recevoir de SMS. Les portables
    (06, 07), les numéros courts (36179...) et les numéros étrangers ne
    sont pas concernés."""
    m = re.fullmatch(r"(?:0|\+33|0033)([1-9])\d{8}", numero or "")
    return bool(m) and m.group(1) not in "67"


def analyser_destinataires_sms(texte):
    """Découpe "Nom <06 12 34 56 78>; 0711223344; ..." en
    ([(nom, numero), ...] sans doublon, [morceaux invalides],
    [doublons écartés : même numéro qu'un destinataire déjà pris],
    [fixes écartés : numéros français qui ne sont pas des portables]).
    Pour les doublons, le premier rencontré est gardé."""
    valides, invalides, doublons, fixes, vus = [], [], [], [], set()
    for morceau in re.split(r"[;,\n]", texte or ""):
        morceau = morceau.strip()
        if not morceau:
            continue
        m = re.fullmatch(r"(.*?)\s*<([^>]*)>", morceau)
        nom, brut = (m.group(1).strip(), m.group(2)) if m else ("", morceau)
        numero = normaliser_numero_sms(brut)
        if not numero:
            invalides.append(morceau)
        elif est_fixe_francais(numero):
            fixes.append(nom or numero)
        elif numero in vus:
            doublons.append(nom or numero)
        else:
            vus.add(numero)
            valides.append((nom, numero))
    return valides, invalides, doublons, fixes


def _guillemets_shell(texte):
    """Protège un texte pour le shell du téléphone (sh) : entre apostrophes."""
    return "'" + texte.replace("'", "'\\''") + "'"


TAILLE_MAX_IMAGE_MMS = 300 * 1024  # accepté par tous les opérateurs
NB_MAX_PHOTOS_SMS = 10             # une photo par MMS (08/10/2026)
DELAI_ENTRE_PHOTOS = 20            # secondes entre deux MMS d'une même personne
SEUIL_ALERTE_MMS = 100             # alerte avant l'envoi au-delà (blocage opérateur)


def duree_envoi_sms(nb_messages, nb_photos, intervalle):
    """Durée estimée pour envoyer nb_messages (≈ 8 s d'automatisme par
    message, plus les délais : DELAI_ENTRE_PHOTOS entre deux photos d'une
    même personne, l'intervalle choisi entre deux destinataires)."""
    par_dest = max(1, nb_photos)
    attente_moyenne = ((par_dest - 1) * DELAI_ENTRE_PHOTOS + intervalle) / par_dest
    minutes = round(nb_messages * (8 + attente_moyenne) / 60)
    if minutes < 1:
        return "moins d'1 min"
    return f"{minutes} min" if minutes < 60 else f"{minutes // 60} h {minutes % 60:02d}"


def preparer_image_mms(source, destination, taille_max=TAILLE_MAX_IMAGE_MMS):
    """Copie réduite de l'image pour un MMS (08/10/2026) : JPEG sur fond
    blanc (transparence des PNG), 1280 px au plus, qualité puis dimensions
    réduites jusqu'à passer sous taille_max. Renvoie la taille en octets."""
    from PySide6.QtGui import QImage, QPainter
    origine = QImage(source)
    if origine.isNull():
        raise ValueError("image illisible")
    cote = 1280
    while True:
        image = origine
        if max(image.width(), image.height()) > cote:
            image = image.scaled(cote, cote, Qt.AspectRatioMode.KeepAspectRatio,
                                 Qt.TransformationMode.SmoothTransformation)
        fond = QImage(image.size(), QImage.Format.Format_RGB32)
        fond.fill(QColor("white"))
        peintre = QPainter(fond)
        peintre.drawImage(0, 0, image)
        peintre.end()
        for qualite in (85, 75, 65, 55, 45):
            if not fond.save(destination, "JPG", qualite):
                raise OSError(f"écriture impossible : {destination}")
            taille = os.path.getsize(destination)
            if taille <= taille_max:
                return taille
        if cote <= 320:
            return taille  # déjà minuscule : on s'en contente
        cote = int(cote * 0.75)


class ThreadEnvoiSMS(QThread):
    """Envoie les SMS un par un par le téléphone relié (voir l'en-tête de
    section). Mêmes signaux que l'envoi de MAILING.py."""
    signal_log = Signal(str)
    signal_progress = Signal(int, int)    # traités, total
    signal_fini = Signal(str)
    signal_countdown = Signal(int)
    signal_pause_forcee = Signal(str)     # téléphone verrouillé, écran inattendu...

    def __init__(self, serie, destinataires, message, intervalle, index_debut=0,
                 images_sources=(), images_pretes=(), photo_debut=0):
        super().__init__()
        self.serie = serie
        self.destinataires = destinataires
        self.message = message
        self.intervalle = max(INTERVALLE_MIN_SMS, intervalle)
        self.index_debut = index_debut
        # MMS (08/10/2026) : photos d'origine (gardées pour REPRENDRE) et
        # leurs versions réduites, déposées sur le téléphone au début de
        # l'envoi. Une photo par MMS : le 1er MMS porte le texte et la 1re
        # photo, les suivants une photo chacun (DELAI_ENTRE_PHOTOS entre eux).
        self.images_sources = list(images_sources)
        self.images_pretes = list(images_pretes)
        self.photo_debut = photo_debut   # reprise au milieu des photos d'un destinataire
        self._uris = []                  # content://media/... une fois référencées
        self._images_distantes = []      # chemins sur le téléphone
        self._stop = False
        self._pause = False

    def stop(self):
        self._stop = True

    def pause(self):
        self._pause = True

    def reprendre(self):
        self._pause = False

    # -- adb --
    def _adb(self, commande, delai=20):
        import subprocess
        try:
            r = subprocess.run([chemin_adb(), "-s", self.serie, "shell", commande],
                               capture_output=True, timeout=delai,
                               stdin=subprocess.DEVNULL, creationflags=subprocess.CREATE_NO_WINDOW)
            return r.stdout.decode("utf-8", "replace") + r.stderr.decode("utf-8", "replace")
        except Exception as e:
            return f"ERREUR adb : {e}"

    def _ecran(self):
        """Arbre des éléments affichés sur le téléphone (ElementTree) ou None."""
        import xml.etree.ElementTree as ET
        sortie = self._adb("uiautomator dump /sdcard/courrier_ui.xml >/dev/null 2>&1; "
                           "cat /sdcard/courrier_ui.xml; rm -f /sdcard/courrier_ui.xml")
        debut = sortie.find("<?xml")
        if debut < 0:
            return None
        try:
            return ET.fromstring(sortie[debut:sortie.rfind(">") + 1])
        except ET.ParseError:
            return None

    @staticmethod
    def _chercher(racine, *, fin_id=None, descriptions=()):
        for n in racine.iter("node"):
            rid = n.get("resource-id", "")
            if fin_id and rid.endswith(fin_id):
                return n
            if descriptions and n.get("content-desc", "") in descriptions:
                return n
        return None

    @staticmethod
    def _centre(noeud):
        x1, y1, x2, y2 = map(int, re.findall(r"\d+", noeud.get("bounds", "")))
        return (x1 + x2) // 2, (y1 + y2) // 2

    def _telephone_pret(self):
        """Réveille l'écran ; False si le téléphone reste verrouillé."""
        if "mWakefulness=Awake" not in self._adb("dumpsys power | grep mWakefulness="):
            self._adb("input keyevent KEYCODE_WAKEUP")
            time.sleep(1)
        return "isKeyguardShowing=true" not in self._adb("dumpsys window | grep isKeyguardShowing")

    def _attendre(self, condition, delai):
        """Relit l'écran jusqu'à ce que condition(racine) renvoie autre chose
        que None, au plus `delai` secondes."""
        fin = time.monotonic() + delai
        while time.monotonic() < fin and not self._stop:
            racine = self._ecran()
            if racine is not None:
                resultat = condition(racine)
                if resultat is not None:
                    return resultat
            time.sleep(0.5)
        return None

    @staticmethod
    def _signature(texte):
        return re.sub(r"\s+", "", texte or "")[:12]

    # -- image (MMS) --
    DOSSIER_IMAGES_TELEPHONE = "/sdcard/Pictures/COURRIER_SMS"

    def _deposer_images(self):
        """Dépose les photos réduites sur le téléphone et les fait
        référencer par sa galerie (une appli SMS ne peut joindre qu'une
        image référencée, via une adresse content://media/...). Renvoie
        True, ou un message d'erreur. Essai à blanc du 08/10/2026 sur
        Samsung / Android 13."""
        import subprocess
        self._adb(f"mkdir -p {self.DOSSIER_IMAGES_TELEPHONE}")
        for k, locale in enumerate(self.images_pretes, 1):
            nom = f"courrier_sms_{int(time.time())}_{k}.jpg"
            distante = f"{self.DOSSIER_IMAGES_TELEPHONE}/{nom}"
            try:
                r = subprocess.run([chemin_adb(), "-s", self.serie, "push", locale, distante],
                                   capture_output=True, timeout=60,
                                   stdin=subprocess.DEVNULL, creationflags=subprocess.CREATE_NO_WINDOW)
                if r.returncode != 0:
                    return (f"impossible de copier la photo {k} sur le téléphone : "
                            + r.stderr.decode("utf-8", "replace").strip())
            except Exception as e:
                return f"impossible de copier la photo {k} sur le téléphone : {e}"
            self._images_distantes.append(distante)
            chemin_reel = distante.replace("/sdcard/", "/storage/emulated/0/")
            self._adb(f"am broadcast -a android.intent.action.MEDIA_SCANNER_SCAN_FILE -d file://{chemin_reel}")
            fin = time.monotonic() + 15
            while True:
                sortie = self._adb("content query --uri content://media/external/images/media --projection _id "
                                   f"--where \"_data LIKE '%{nom}'\"")
                m = re.search(r"_id=(\d+)", sortie)
                if m:
                    self._uris.append(f"content://media/external/images/media/{m.group(1)}")
                    break
                if time.monotonic() > fin:
                    return f"le téléphone n'a pas référencé la photo {k}"
                time.sleep(1)
        return True

    def _retirer_images(self):
        """Supprime les photos déposées sur le téléphone (galerie comprise)."""
        for uri in self._uris:
            self._adb(f"content delete --uri {uri}")
        for distante in self._images_distantes:
            self._adb(f"rm -f {distante}")
        self._uris, self._images_distantes = [], []

    def _envoyer_un(self, numero, texte, uri_image=""):
        """True si envoyé, sinon message d'erreur. uri_image : photo jointe
        (MMS), sinon simple SMS."""
        # Nouvelle tâche à chaque SMS (NEW_TASK | CLEAR_TASK) : l'appli
        # s'ouvre forcément sur la conversation de CE numéro.
        if uri_image:
            # Avec image : "partager l'image" vers l'appli SMS par défaut
            # (l'ouverture sms:... ignore la pièce jointe chez Samsung)
            appli = self._adb("settings get secure sms_default_application").strip()
            paquet = f"-p {appli} " if re.fullmatch(r"[\w.]+", appli) and appli != "null" else ""
            self._adb(f"am start -f 0x10008000 -a android.intent.action.SEND -t image/jpeg {paquet}"
                      f"--es address {numero} --es sms_body {_guillemets_shell(texte)} "
                      f"--eu android.intent.extra.STREAM {uri_image} --grant-read-uri-permission")
        else:
            self._adb(f"am start -f 0x10008000 -a android.intent.action.SENDTO "
                      f"-d sms:{numero} --es sms_body {_guillemets_shell(texte)}")
        signature = self._signature(texte)

        def _image_jointe(racine):
            # Seulement la zone de saisie (pas par la description "Image
            # jointe" : les bulles des MMS déjà échangés dans la conversation
            # la portent aussi — un MMS bien parti était annoncé en échec,
            # 1er vrai essai du 08/10/2026)
            return (self._chercher(racine, fin_id=":id/attachment_editor_layout") is not None
                    or self._chercher(racine, fin_id=":id/attach_content_view") is not None)

        def _bouton_si_pret(racine):
            champ = self._chercher(racine, fin_id=":id/message_edit_text")
            if champ is None:
                champ = next((n for n in racine.iter("node")
                              if n.get("class") == "android.widget.EditText"), None)
            if champ is None or not self._signature(champ.get("text")).startswith(signature[:8]):
                return None
            if uri_image and not _image_jointe(racine):
                return None
            return self._chercher(racine, fin_id=":id/send_button",
                                  descriptions=("Envoyer", "Send", "Envoyer un SMS", "Send SMS"))

        bouton = self._attendre(_bouton_si_pret, 15 if uri_image else 10)
        if bouton is None:
            return ("message, image ou bouton Envoyer introuvable à l'écran" if uri_image
                    else "message ou bouton Envoyer introuvable à l'écran")
        x, y = self._centre(bouton)
        self._adb(f"input tap {x} {y}")

        def _parti(racine):
            champ = self._chercher(racine, fin_id=":id/message_edit_text")
            if champ is None:
                return None
            if signature and self._signature(champ.get("text")).startswith(signature[:8]):
                return None  # le texte est encore là
            if uri_image and _image_jointe(racine):
                return None  # l'image est encore là
            return True

        if self._attendre(_parti, 15 if uri_image else 10):
            return True
        return "le message est resté dans le champ de saisie (non parti ?)"

    def _vider_champ(self):
        """Efface le texte (et l'image) restés dans le champ de saisie du
        téléphone (sinon l'appli les garderait en brouillon et les
        doublerait à la reprise)."""
        racine = self._ecran()
        if racine is None:
            return
        croix = self._chercher(racine, fin_id=":id/attach_delete_button")
        if croix is None and self._chercher(racine, fin_id=":id/attach_content_view") is not None:
            # Image jointe mais croix invisible (téléphone à l'horizontale :
            # le clavier la cache) : on ferme le clavier puis on relit l'écran
            self._adb("input keyevent KEYCODE_BACK")
            time.sleep(1)
            racine = self._ecran()
            croix = racine is not None and self._chercher(racine, fin_id=":id/attach_delete_button")
            croix = croix if croix is not False else None
        if croix is not None:
            x, y = self._centre(croix)
            self._adb(f"input tap {x} {y}")
            time.sleep(1)
            racine = self._ecran()
        champ = racine is not None and self._chercher(racine, fin_id=":id/message_edit_text")
        if champ is not None and champ is not False:
            x, y = self._centre(champ)
            self._adb(f"input tap {x} {y}; input keycombination 113 29; input keyevent KEYCODE_DEL")

    def _pause_forcee(self, raison, index, photo=0):
        self._pause = True
        self._sauvegarder_progression(index, photo)
        self.signal_pause_forcee.emit(raison)

    def _patienter(self, secondes):
        """Décompte affiché, interruptible (ARRÊTER) et suspendu par PAUSE."""
        for sec in range(secondes, 0, -1):
            if self._stop:
                break
            while self._pause and not self._stop:
                time.sleep(0.5)
            self.signal_countdown.emit(sec)
            time.sleep(1)
        self.signal_countdown.emit(0)

    def run(self):
        total = len(self.destinataires)
        nb_photos = len(self.images_pretes)
        par_destinataire = max(1, nb_photos)        # messages par destinataire
        total_messages = total * par_destinataire
        i, j = self.index_debut, self.photo_debut   # destinataire, photo
        nb_envoyes = 0
        # Seuil anti-rafale d'Android (≈30 SMS / 30 min, puis demande de
        # confirmation qui bloquerait l'envoi) relevé le temps de l'envoi.
        seuil_avant = self._adb("settings get global sms_outgoing_check_max_count").strip()
        self._adb("settings put global sms_outgoing_check_max_count 100000")
        genre = "MMS" if nb_photos else "SMS"
        try:
            if nb_photos:
                resultat = self._deposer_images()
                if resultat is not True:
                    if i or j:
                        self._sauvegarder_progression(i, j)
                    self.signal_log.emit(f"✗ Photos : {resultat}")
                    self.signal_fini.emit(f"Envoi non effectué : {resultat}."
                                          + (" Reprise possible." if i or j else ""))
                    return
            while i < total:
                while self._pause and not self._stop:
                    time.sleep(0.5)
                if self._stop:
                    self._sauvegarder_progression(i, j)
                    self.signal_fini.emit(f"Arrêté à {i}/{total}. Reprise possible.")
                    return
                if not self._telephone_pret():
                    self._pause_forcee("Téléphone verrouillé : déverrouillez-le puis cliquez REPRENDRE.", i, j)
                    continue
                nom, numero = self.destinataires[i]
                libelle = (f"{nom} ({formater_numero_telephone(numero)})" if nom
                           else formater_numero_telephone(numero))
                if nb_photos > 1:
                    libelle += f" — photo {j + 1}/{nb_photos}"
                # Texte seulement avec le 1er MMS ; les suivants : photo seule
                texte = "" if j else normaliser_texte_sms(
                    self.message.replace("{nom}", nom or "").replace("  ", " "))
                resultat = self._envoyer_un(numero, texte, self._uris[j] if nb_photos else "")
                # ARRÊTER pendant l'envoi : un message bien parti est quand
                # même compté (sinon REPRENDRE l'enverrait une 2e fois)
                if self._stop and resultat is not True:
                    continue
                if resultat is not True:
                    self._vider_champ()
                    self.signal_log.emit(f"✗ {libelle} — {resultat}")
                    self._pause_forcee(f"Échec pour {libelle} : {resultat}.\n"
                                       "Regardez l'écran du téléphone, puis REPRENDRE "
                                       "(le même message sera retenté).", i, j)
                    continue
                nb_envoyes += 1
                self.signal_log.emit(f"✓ {libelle}")
                j += 1
                if j >= par_destinataire:  # destinataire terminé
                    i, j = i + 1, 0
                self.signal_progress.emit(i * par_destinataire + j, total_messages)
                self._sauvegarder_progression(i, j)
                if i < total:
                    # Entre deux photos d'une même personne : délai court ;
                    # entre deux destinataires : l'intervalle choisi
                    self._patienter(DELAI_ENTRE_PHOTOS if j else self.intervalle)
            self.signal_fini.emit(f"Terminé ! {nb_envoyes} {genre} envoyés "
                                  f"({total} destinataire(s)).")
        finally:
            self._retirer_images()
            if seuil_avant.isdigit():
                self._adb(f"settings put global sms_outgoing_check_max_count {seuil_avant}")
            else:
                self._adb("settings delete global sms_outgoing_check_max_count")

    def _sauvegarder_progression(self, index, photo=0):
        try:
            with open(FICHIER_PROGRESSION_SMS, "w", encoding="utf-8") as f:
                json.dump({"index": index, "photo": photo, "destinataires": self.destinataires,
                           "message": self.message, "images": self.images_sources},
                          f, ensure_ascii=False, indent=2)
        except Exception:
            pass


