def construire_entete_colonne_pj(layout_colonne, au_clic):
    """Haut de la colonne des pièces jointes (08/10/2026, demandé) : gros
    bouton rouge qui ouvre le choix de fichiers de Windows, et en dessous
    l'explication — beaucoup de gens ne savent pas glisser un fichier d'une
    fenêtre à l'autre. Même présentation dans Rédiger et dans SMS.
    Renvoie (bouton, étiquette)."""
    bouton = QPushButton("+  PIÈCES JOINTES")
    bouton.setStyleSheet(STYLE_GROS_BOUTON_PJ)
    bouton.setCursor(Qt.CursorShape.PointingHandCursor)
    bouton.clicked.connect(au_clic)
    layout_colonne.addWidget(bouton)
    etiquette = QLabel(TEXTE_AIDE_PIECES_JOINTES)
    # Gris très clair, sans italique (08/10/2026 : plus lisible, même taille)
    etiquette.setStyleSheet("color: #e6e6e6; font-family: Verdana; font-size: 10px; border: none;")
    etiquette.setWordWrap(True)
    etiquette.setAlignment(Qt.AlignmentFlag.AlignCenter)
    layout_colonne.addWidget(etiquette)
    return bouton, etiquette


