COMPTES = charger_comptes()


def est_envoye_par_moi(de, compte_actif=None):
    """Vrai si l'expéditeur `de` est l'adresse du compte affiché (07/10/2026).
    Sert à reconnaître un mail envoyé quel que soit le dossier où il se
    trouve — Envoyés sous tous leurs noms ([Gmail] Messages envoyés,
    Éléments envoyés, INBOX_OUTBOX…), mais aussi Corbeille, Archive, Tous les
    messages ou dossiers créés par l'utilisateur : le correspondant à
    afficher et à filtrer (👤) est alors le destinataire, pas soi-même.
    Seul le compte affiché compte : un mail venu d'un AUTRE de mes comptes
    (tests "DE MOI A FREE"…) est, pour celui-ci, un mail reçu."""
    from email.utils import parseaddr
    adresse = parseaddr(de or "")[1].lower()
    if not adresse:
        return False
    if compte_actif:
        return adresse == (compte_actif.get("adresse") or "").lower()
    return any(adresse == (c.get("adresse") or "").lower() for c in COMPTES)


_NOMS_DOSSIERS_ENVOYES = {"sent", "sent items", "sent messages", "sent-mail", "sent mail",
                          "envoyés", "envoyes", "éléments envoyés", "elements envoyes",
                          "messages envoyés", "messages envoyes", "outbox"}


def est_dossier_envoyes(nom):
    """Reconnaît le dossier des mails envoyés sous ses différents noms
    (07/10/2026) : INBOX.Sent, Sent, [Gmail]/Messages envoyés (y compris
    encodé "envoy&AOk-s"), Éléments envoyés (Outlook), INBOX_OUTBOX (Orange),
    INBOX_sent-mail (Free)… — on compare le dernier segment du nom."""
    nom = (nom or "").replace("&AOk-", "é").replace("&AMk-", "É").lower()
    nom = nom.replace("/", ".").rsplit(".", 1)[-1]
    # Préfixes collés par "_" : INBOX_OUTBOX, [Gmail]_… (nom sur disque)
    prefixe, _, reste = nom.partition("_")
    if reste and (prefixe == "inbox" or prefixe.endswith("]")):
        nom = reste
    return nom.strip() in _NOMS_DOSSIERS_ENVOYES


def correspondant_destinataire(de, a, compte_actif=None, force=False):
    """Pour un mail envoyé par moi (ou force=True : dossier Envoyés), le
    1er destinataire autre que le compte affiché, sous la forme
    "Nom <adresse>" ; "" sinon. Un mail envoyé à soi-même n'a pas d'autre
    correspondant : on garde alors l'expéditeur (comportement d'avant)."""
    if not (force or est_envoye_par_moi(de, compte_actif)):
        return ""
    from email.utils import getaddresses
    for nom, adresse in getaddresses([a or ""]):
        if adresse and not est_envoye_par_moi(adresse, compte_actif):
            return f"{nom} <{adresse}>" if nom else adresse
    return ""

def _migrer_dossiers_bcc_vers_at():
    """Migration ponctuelle et idempotente (07/07/2026) : le journal des
    CCI/BCC (fichiers .bcc) écrivait son dossier de stockage sous l'adresse
    brute du compte (utilisateur@exemple.org) alors que tout le reste du cache
    (mails, _meta.json...) utilise la forme utilisateur_at_exemple.org — deux
    dossiers séparés par compte, sans perte de données (les deux systèmes
    ne se relisaient jamais l'un l'autre) mais source de confusion sur le
    disque. On regroupe les .bcc déjà écrits dans l'ancien dossier vers le
    nouveau. Sans effet dès que l'ancien dossier n'existe plus (ce qui sera
    le cas dès le lancement suivant), donc sans risque à l'exécuter à
    chaque démarrage."""
    for compte in COMPTES:
        adresse_brute = compte.get("adresse", "")
        adresse_safe = adresse_brute.replace("@", "_at_")
        if not adresse_brute or adresse_safe == adresse_brute:
            continue
        ancien = os.path.join(DOSSIER_STORAGE, adresse_brute)
        if not os.path.isdir(ancien):
            continue
        nouveau = os.path.join(DOSSIER_STORAGE, adresse_safe)
        try:
            os.makedirs(nouveau, exist_ok=True)
            for nom in os.listdir(ancien):
                src = os.path.join(ancien, nom)
                dst = os.path.join(nouveau, nom)
                if os.path.isfile(src) and not os.path.exists(dst):
                    os.rename(src, dst)
            if not os.listdir(ancien):
                os.rmdir(ancien)
        except Exception as e:
            print(f"[MIGRATION BCC] Erreur pour {adresse_brute} : {e}")

_migrer_dossiers_bcc_vers_at()

