EXTENSIONS_PJ_DANGEREUSES = frozenset({
    ".exe", ".com", ".scr", ".pif", ".bat", ".cmd", ".msi", ".msp", ".msc",
    ".vbs", ".vbe", ".js", ".jse", ".wsf", ".wsh", ".hta", ".ps1", ".psm1",
    ".lnk", ".url", ".reg", ".cpl", ".jar", ".appref-ms", ".application",
    ".iso", ".img", ".vhd", ".vhdx", ".chm", ".scf", ".inf", ".gadget",
    ".py", ".pyw", ".dll", ".sys", ".settingcontent-ms", ".library-ms",
})

def marquer_provenance_internet(chemin):
    """Ajoute la marque Windows "téléchargé depuis Internet" (flux NTFS
    Zone.Identifier, zone 3) — celle que pose un navigateur. Sans elle,
    une PJ ouverte depuis COURRIER échappait à SmartScreen et Office
    exécutait ses macros sans le bandeau "Mode protégé"."""
    try:
        with open(chemin + ":Zone.Identifier", "w", encoding="ascii") as f:
            f.write("[ZoneTransfer]\r\nZoneId=3\r\n")
    except Exception as e:
        print(f"[SECURITE] Marquage Internet impossible pour {chemin} : {e}")

def _decoder_payload(payload_bytes, charset):
    """Essaie de décoder avec le charset donné, puis UTF-8, puis latin-1."""
    # Essayer d'abord le charset déclaré
    if charset and charset.lower() not in ("utf-8", "utf8"):
        try:
            return payload_bytes.decode(charset, errors="strict")
        except Exception:
            pass
    # Essayer UTF-8 strict
    try:
        return payload_bytes.decode("utf-8", errors="strict")
    except Exception:
        pass
    # Fallback latin-1
    return payload_bytes.decode("latin-1", errors="replace")

class ExtracteurTexteHTML(HTMLParser):
    """Extrait le texte visible d'un fragment HTML, en ignorant le contenu
    des balises <style> et <script>. Sans ça, le CSS d'une newsletter
    (souvent placé en clair dans un <style> plutôt que dans un fichier
    externe) est traité comme du texte normal par HTMLParser et s'affiche
    tel quel — par exemple dans une citation de réponse."""
    def __init__(self):
        super().__init__()
        self.texte = []
        self._profondeur_a_ignorer = 0

    def handle_starttag(self, tag, attrs):
        if tag in ("style", "script"):
            self._profondeur_a_ignorer += 1

    def handle_endtag(self, tag):
        if tag in ("style", "script") and self._profondeur_a_ignorer > 0:
            self._profondeur_a_ignorer -= 1

    def handle_data(self, data):
        if not self._profondeur_a_ignorer:
            self.texte.append(data)

def nettoyer_html_pour_citation(html):
    """Nettoie le HTML d'un message original avant de le citer dans une
    réponse : retire <style>/<script> (sinon leurs règles s'appliqueraient
    à toute la fenêtre de rédaction, pas seulement à la citation — un
    `body {...}` ou `p {...}` de newsletter écraserait par exemple la
    police Verdana partout) et les balises de structure de document
    (<!DOCTYPE>, <html>, <head>, <body>), pour ne garder que le contenu
    réel (paragraphes, images...), intégrable proprement dans un simple
    <div> sans rien casser autour."""
    if not html:
        return ""
    html = re.sub(r'(?is)<style[^>]*>.*?</style>', '', html)
    html = re.sub(r'(?is)<script[^>]*>.*?</script>', '', html)
    html = re.sub(r'(?is)<!DOCTYPE[^>]*>', '', html)
    html = re.sub(r'(?is)</?html[^>]*>', '', html)
    html = re.sub(r'(?is)<head[^>]*>.*?</head>', '', html)
    html = re.sub(r'(?is)</?body[^>]*>', '', html)
    return html.strip()

def extraire_texte_visible(html):
    """Raccourci pratique : texte visible d'un fragment HTML, espaces
    normalisés, balises <style>/<script> ignorées."""
    extracteur = ExtracteurTexteHTML()
    try:
        extracteur.feed(html or "")
    except Exception:
        pass
    return " ".join(extracteur.texte).strip()

_MOTIF_URL_AUTOLIEN = re.compile(r'\b((?:https?://|www\.)[^\s<>"\']+)')

def _remplacer_url_par_lien(segment_texte):
    def remplacer(m):
        brut = m.group(1)
        ponctuation_finale = ""
        while brut and brut[-1] in '.,;:!?)':
            ponctuation_finale = brut[-1] + ponctuation_finale
            brut = brut[:-1]
        if not brut:
            return m.group(0)
        href = brut if brut.startswith("http") else f"https://{brut}"
        return f'<a href="{href}">{brut}</a>{ponctuation_finale}'
    return _MOTIF_URL_AUTOLIEN.sub(remplacer, segment_texte)

def auto_lien_texte(html):
    """Transforme les URL tapées en texte brut (sans passer par le bouton
    lien) en liens cliquables, dans le corps d'un e-mail. Découpe le HTML
    en segments tag/texte pour n'agir que sur le texte visible : ignore le
    contenu déjà à l'intérieur d'une balise <a>, pour ne jamais transformer
    un lien déjà existant ni toucher la structure HTML elle-même."""
    segments = re.split(r'(<[^>]+>)', html or "")
    dans_lien = 0
    resultat = []
    for segment in segments:
        if segment.startswith('<') and segment.endswith('>'):
            if re.match(r'(?i)^<a[\s>]', segment):
                dans_lien += 1
            elif re.match(r'(?i)^</a\s*>$', segment):
                dans_lien = max(0, dans_lien - 1)
            resultat.append(segment)
        else:
            resultat.append(segment if dans_lien > 0 else _remplacer_url_par_lien(segment))
    return "".join(resultat)

SEUIL_IMAGE_AFFICHAGE_OCTETS = 3 * 1024 * 1024
SEUIL_IMAGE_AFFICHAGE_PX     = 2500
TAILLE_IMAGE_AFFICHAGE_PX    = 2000

def image_pour_affichage(data, mime):
    """Réduit une image démesurée avant son intégration en base64 dans le
    .html (29/09/2026 : photo 5472x3648 de 18 Mo dans « SUPERCROSS DE
    PARIS » de Médiacross → .html de 27,5 Mo). Au-delà de 3 Mo ou de
    2500 px, l'image est ramenée à 2000 px sur son plus grand côté. Ne sert
    QU'À l'affichage : la pièce jointe d'origine reste intacte pour
    « Enregistrer ». Retourne (data, mime), inchangés en cas de doute
    (GIF animés, SVG, échec de décodage)."""
    if mime not in ("image/jpeg", "image/png", "image/webp", "image/bmp", "image/tiff"):
        return data, mime
    try:
        from PySide6.QtGui import QImageReader
        from PySide6.QtCore import QBuffer, QByteArray, QIODevice
        tampon = QBuffer()
        tampon.setData(QByteArray(data))
        tampon.open(QIODevice.ReadOnly)
        lecteur = QImageReader(tampon)
        taille = lecteur.size()
        if (len(data) <= SEUIL_IMAGE_AFFICHAGE_OCTETS and
                max(taille.width(), taille.height()) <= SEUIL_IMAGE_AFFICHAGE_PX):
            return data, mime
        # Orientation EXIF appliquée : elle serait perdue au ré-encodage.
        lecteur.setAutoTransform(True)
        image = lecteur.read()
        if image.isNull():
            return data, mime
        if max(image.width(), image.height()) > TAILLE_IMAGE_AFFICHAGE_PX:
            image = image.scaled(TAILLE_IMAGE_AFFICHAGE_PX, TAILLE_IMAGE_AFFICHAGE_PX,
                                 Qt.KeepAspectRatio, Qt.SmoothTransformation)
        format_sortie, mime_sortie = (("PNG", "image/png") if image.hasAlphaChannel()
                                      else ("JPG", "image/jpeg"))
        sortie = QBuffer()
        sortie.open(QIODevice.WriteOnly)
        if not image.save(sortie, format_sortie, 85):
            return data, mime
        reduite = bytes(sortie.data())
        if not reduite or len(reduite) >= len(data):
            return data, mime
        return reduite, mime_sortie
    except Exception:
        return data, mime

def data_uri_affichage(data, mime):
    """data URI d'une image intégrée au corps d'un mail, réduite si démesurée
    (voir image_pour_affichage)."""
    import base64
    data, mime = image_pour_affichage(data, mime)
    return f"data:{mime};base64,{base64.b64encode(data).decode('ascii')}"


def _assembler_html_fragmente(msg):
    """Recolle le corps d'un mail Apple Mail : multipart/mixed contenant au
    moins deux text/html enfants directs, intercalés avec des images/PDF.
    Les fragments sont mis bout à bout (contenu de leur <body> seulement) et
    les images en ligne sans Content-ID sont replacées à leur position.
    Retourne "" si le mail n'a pas cette structure."""
    import base64
    import re as _re

    def _est_pj(part):
        return "attachment" in str(part.get("Content-Disposition", "")).lower()

    def _html_de(part):
        data = part.get_payload(decode=True)
        if not data:
            return ""
        html = _decoder_payload(data, part.get_content_charset())
        html = _re.sub(r"(?is)<head\b.*?</head>", "", html)
        m = _re.search(r"(?is)<body\b[^>]*>(.*)</body>", html)
        if m:
            html = m.group(1)
        return _re.sub(r"(?is)</?(html|body)\b[^>]*>", "", html)

    for conteneur in msg.walk():
        if conteneur.get_content_type() != "multipart/mixed":
            continue
        enfants = conteneur.get_payload()
        if not isinstance(enfants, list):
            continue
        nb_html = sum(1 for e in enfants
                      if e.get_content_type() == "text/html" and not _est_pj(e))
        if nb_html < 2:
            continue
        morceaux = []
        for e in enfants:
            if _est_pj(e):
                continue
            ct = e.get_content_type()
            if ct == "text/html":
                morceaux.append(_html_de(e))
            elif ct == "multipart/alternative":
                html_alt = next((p for p in e.walk()
                                 if p.get_content_type() == "text/html"), None)
                if html_alt is not None:
                    morceaux.append(_html_de(html_alt))
            elif ct.startswith("image/") and not e.get("Content-ID"):
                data = e.get_payload(decode=True)
                if data:
                    morceaux.append(f'<div><img src="{data_uri_affichage(data, ct)}" '
                                    f'style="max-width:100%;"></div>')
        return "<html><body>" + "".join(morceaux) + "</body></html>"
    return ""


def extraire_corps(msg):
    content_type = msg.get_content_type()
    corps_texte = ""
    corps_html = ""

    # Pour les bounces (multipart/report, delivery-status) → prioriser text/plain
    sujet_decode = decoder_entete(msg.get("Subject", "") or "").lower()
    from_decode  = decoder_entete(msg.get("From", "") or "").lower()
    est_bounce = content_type == "multipart/report" or \
                 "delivery" in sujet_decode or \
                 "undelivered" in sujet_decode or \
                 "postmaster" in from_decode or \
                 "mailer-daemon" in from_decode

    if msg.is_multipart():
        for part in msg.walk():
            ct = part.get_content_type()
            cd = str(part.get("Content-Disposition", ""))
            if "attachment" in cd:
                continue
            # Pour les bounces, s'arrêter à la première partie texte
            if est_bounce and ct == "text/plain" and not corps_texte:
                charset = part.get_content_charset()
                payload_bytes = part.get_payload(decode=True)
                if payload_bytes:
                    corps_texte = _decoder_payload(payload_bytes, charset)
                    break
            elif not est_bounce or (est_bounce and ct == "text/html"):
                charset = part.get_content_charset()
                payload_bytes = part.get_payload(decode=True)
                if payload_bytes is None:
                    continue
                if ct == "text/plain" and not corps_texte:
                    corps_texte = _decoder_payload(payload_bytes, charset)
                elif ct == "text/html" and not corps_html:
                    corps_html = _decoder_payload(payload_bytes, charset)
    else:
        charset = msg.get_content_charset()
        payload_bytes = msg.get_payload(decode=True)
        if payload_bytes:
            payload = _decoder_payload(payload_bytes, charset)
            if content_type == "text/html":
                corps_html = payload
            else:
                corps_texte = payload

    # Apple Mail (29/09/2026) : un mail avec images/PDF insérés dans le texte
    # arrive découpé en plusieurs text/html intercalés avec les pièces dans
    # un multipart/mixed. Seul le premier fragment était gardé — souvent vide
    # (« MX DES NATIONS - J-3 ! » de Médiacross : corps entièrement blanc).
    if msg.is_multipart() and not est_bounce:
        html_fragmente = _assembler_html_fragmente(msg)
        if html_fragmente:
            corps_html = html_fragmente

    import html as _html_mod
    if est_bounce and corps_texte:
        return f"<pre style='font-family:Verdana;font-size:11px;white-space:pre-wrap;padding:10px;'>{_html_mod.escape(corps_texte)}</pre>"
    return corps_html if corps_html else _html_mod.escape(corps_texte).replace("\n", "<br>")
