def generer_html_macro(macro):
    """Construit le HTML à insérer dans le corps du mail à partir des
    étapes d'une macro. Le contenu du presse-papiers est lu au moment de
    l'exécution (pas figé dans la macro elle-même)."""
    morceaux = []
    for etape in macro.get("etapes", []):
        type_etape = etape.get("type")
        if type_etape == "texte":
            morceaux.append(html.escape(etape.get("valeur", "")))
        elif type_etape == "saut_ligne":
            morceaux.append("<br>")
        elif type_etape == "presse_papiers":
            mime = QApplication.clipboard().mimeData()
            if mime.hasHtml():
                morceaux.append(mime.html())
            elif mime.hasText():
                morceaux.append(html.escape(mime.text()).replace("\n", "<br>"))
    return "".join(morceaux)

def appliquer_variables_modele(html_modele, de="", date="", pour="", cc="", sujet="", corps=""):
    """Remplace les variables {{...}} d'un modèle par leur valeur réelle.
    {{CURSEUR}} devient un marqueur <span id="__curseur_modele__"> que
    FenetreRedaction retrouve directement dans le DOM pour y placer le
    curseur — plus fiable qu'un indice de caractères, qui se révèle ambigu
    dès que le modèle contient surtout des images/séparateurs sans texte à
    proximité du curseur.

    corps est déjà du HTML structuré (paragraphes, images...), nettoyé par
    nettoyer_html_pour_citation — pas du texte brut à reformater en <br>,
    qui ferait perdre toute la mise en page du message original cité."""
    html = html_modele or ""

    # Garde-fou (07/08/2026, bug remonté par l'utilisateur : le curseur se
    # plaçait dans le contenu cité d'un très ancien message plutôt que dans
    # le nouveau, à cause d'un marqueur __curseur_modele__ resté par erreur
    # dans ce message historique — jamais retiré à l'époque pour une
    # raison qui reste à élucider si ça se reproduit) : getElementById()
    # renvoie le PREMIER élément portant cet identifiant dans le document,
    # peu importe lequel est "le bon" — s'il y en a deux (le neuf +
    # celui-ci resté dans le corps cité), le résultat devient imprévisible.
    # On neutralise donc systématiquement tout marqueur déjà présent dans
    # le corps cité AVANT d'y insérer le marqueur du nouveau message, pour
    # garantir qu'il n'y en ait jamais qu'un seul dans le HTML final.
    corps = (corps or "").replace('id="__curseur_modele__"', '')

    # Construire le bloc de citation complet (De/Date/Pour/Cc/Sujet + corps cité)
    # uniquement si au moins un de ces éléments est renseigné (nouveau message
    # sans citation sinon)
    citation = ""
    if any([de, date, pour, cc, sujet, corps]):
        citation = (
            '<div style="border-top:1px solid #999;padding-top:8px;margin-top:8px;'
            'font-family:Verdana;font-size:11px;color:#333;">'
            f'<b>De:</b> {de}<br>'
            f'<b>Date:</b> {date}<br>'
            f'<b>Pour:</b> {pour}<br>'
            f'<b>Cc:</b> {cc}<br>'
            f'<b>Sujet:</b> {sujet}'
            '</div>'
            f'<div style="margin-top:8px;">{corps}</div>'
        )

    remplacements = {
        "{{DE}}": de,
        "{{DATE}}": date,
        "{{POUR}}": pour,
        "{{CC}}": cc,
        "{{SUJET}}": sujet,
        "{{CORPS}}": corps,
    }
    for balise, valeur in remplacements.items():
        html = html.replace(balise, valeur)

    # {{CITATION}} : si le modèle la place explicitement, on substitue à cet
    # endroit. Sinon (cas normal — le gestionnaire de modèles ne propose pas
    # de marqueur à placer soi-même), elle suit automatiquement le contenu
    # rédigé, comme dans n'importe quelle messagerie standard.
    if "{{CITATION}}" in html:
        html = html.replace("{{CITATION}}", citation)
    elif citation:
        html += citation

    html = html.replace("{{CURSEUR}}", '<span id="__curseur_modele__"></span>')

    return html

