        class ChampTexteNatif(QLineEdit):
            """QLineEdit qui reprend systématiquement le focus natif Windows
            au clic — nécessaire car le widget CEF voisin (HWND natif enfant)
            peut sinon garder la main sur le clavier au niveau du système.
            Si normaliser_adresses=True, le collage reformate automatiquement
            plusieurs adresses email séparées par espaces/virgules/retours à
            la ligne en une liste propre séparée par '; '."""
            def __init__(self, *args, normaliser_adresses=False, **kwargs):
                super().__init__(*args, **kwargs)
                self._normaliser_adresses = normaliser_adresses

            def mousePressEvent(self, event):
                super().mousePressEvent(event)
                self.setFocus()
                # Le SetFocus() Win32 bas niveau via ctypes, présent ici à
                # l'origine, a été retiré le 25/07/2026 : c'était un
                # contournement pour CEF (fenêtre native qui pouvait voler
                # le focus clavier), obsolète depuis le passage à
                # QtWebEngine. Il provoquait un flash blanc dans le bandeau
                # À/Cc/Cci/Sujet au clic (repaint forcé en plein milieu du
                # traitement Qt du clic), signalé le 25/07/2026.

            def insertFromMimeData(self, source):
                if not self._normaliser_adresses or not source.hasText():
                    super().insertFromMimeData(source)
                    return
                import re
                texte = source.text().strip()
                # Normaliser les séparateurs : retours à la ligne et virgules → ";"
                texte_norm = re.sub(r'[\r\n]+', ';', texte)
                texte_norm = re.sub(r',', ';', texte_norm)
                # Extraire les blocs adresse (format "Nom <email>" ou email simple)
                blocs = re.findall(
                    r'"[^"]*"\s*<[^>]+@[^>]+>'   # "Nom" <email>
                    r'|[^<;][^<;]*<[^>]+@[^>]+>' # Nom <email>
                    r'|[^\s,;<>"]+@[^\s,;<>"]+',  # email simple
                    texte_norm)
                if blocs:
                    self.insert("; ".join(b.strip() for b in blocs))
                else:
                    super().insertFromMimeData(source)

        class ChampDestinataires(QTextEdit):
            """Champ multi-lignes pour À/Cc/Cci (ajouté le 25/07/2026, à la
            demande de l'utilisateur) : contrairement à un QLineEdit, il
            s'agrandit automatiquement en hauteur (jusqu'à LIGNES_MAX
            lignes, puis défilement interne) au lieu de faire disparaître
            les destinataires en trop en bout de ligne unique — gênant pour
            vérifier une longue liste de destinataires.
            Fournit text()/setText()/cursorPosition()/setCursorPosition()
            pour rester compatible avec le reste du code, écrit à l'origine
            pour un QLineEdit."""
            LIGNES_MAX = 4

            def __init__(self, valeur="", normaliser_adresses=False, parent=None):
                super().__init__(parent)
                self._normaliser_adresses = normaliser_adresses
                self.setAcceptRichText(False)
                self.setLineWrapMode(QTextEdit.LineWrapMode.WidgetWidth)
                self.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
                self.setVerticalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAsNeeded)
                self.setTabChangesFocus(True)
                self.setPlainText(valeur)
                self.document().contentsChanged.connect(self._ajuster_hauteur)
                self._ajuster_hauteur()

            def _ajuster_hauteur(self):
                marges = self.contentsMargins()
                fm = QFontMetrics(self.font())
                ligne_h = fm.lineSpacing()
                hauteur_doc = self.document().size().height()
                hauteur_max = ligne_h * self.LIGNES_MAX + marges.top() + marges.bottom() + 10
                hauteur_min = ligne_h + marges.top() + marges.bottom() + 10
                nouvelle_hauteur = min(max(hauteur_doc + marges.top() + marges.bottom() + 8, hauteur_min), hauteur_max)
                self.setFixedHeight(int(nouvelle_hauteur))
                self.setVerticalScrollBarPolicy(
                    Qt.ScrollBarPolicy.ScrollBarAsNeeded
                    if hauteur_doc + 10 > hauteur_max
                    else Qt.ScrollBarPolicy.ScrollBarAlwaysOff
                )

            def keyPressEvent(self, event):
                # Si le popup d'autocomplétion est ouvert, Entrée doit
                # valider la suggestion surlignée (navigation aux flèches),
                # pas passer au champ suivant. Corrigé le 28/07/2026: sans
                # cette vérification, Entrée hijackait la touche AVANT que
                # la complétion ait pu réagir, laissant le texte partiel
                # tapé (ex. "prenom") au lieu de la suggestion complète
                # (ex. "prenom <prenom@free.fr>") — seul un clic
                # souris sur la suggestion fonctionnait correctement.
                completeur = getattr(self, '_completeur_carnet', None)
                if completeur is not None and completeur.popup().isVisible():
                    if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
                        index = completeur.popup().currentIndex()
                        if index.isValid():
                            texte = completeur.completionModel().data(
                                index, Qt.ItemDataRole.DisplayRole)
                            completeur.popup().hide()
                            completeur.activated.emit(texte)
                        else:
                            completeur.popup().hide()
                        return
                    # Laisser les autres touches (flèches, Échap...) au
                    # comportement normal de navigation dans le popup.
                    super().keyPressEvent(event)
                    return
                # Un retour à la ligne n'a pas de sens dans une liste de
                # destinataires — Entrée passe au champ suivant, comme Tab.
                if event.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
                    self.focusNextChild()
                    return
                super().keyPressEvent(event)

            def mousePressEvent(self, event):
                super().mousePressEvent(event)
                self.setFocus()

            def insertFromMimeData(self, source):
                if not self._normaliser_adresses or not source.hasText():
                    super().insertFromMimeData(source)
                    return
                import re
                texte = source.text().strip()
                texte_norm = re.sub(r'[\r\n]+', ';', texte)
                texte_norm = re.sub(r',', ';', texte_norm)
                blocs = re.findall(
                    r'"[^"]*"\s*<[^>]+@[^>]+>'
                    r'|[^<;][^<;]*<[^>]+@[^>]+>'
                    r'|[^\s,;<>"]+@[^\s,;<>"]+',
                    texte_norm)
                if blocs:
                    self.insertPlainText("; ".join(b.strip() for b in blocs))
                else:
                    super().insertFromMimeData(source)

            # Compatibilité avec le code existant, écrit pour QLineEdit
            def text(self):
                return self.toPlainText()

            def setText(self, texte):
                self.setPlainText(texte)

            def cursorPosition(self):
                return self.textCursor().position()

            def setCursorPosition(self, position):
                curseur = self.textCursor()
                curseur.setPosition(position)
                self.setTextCursor(curseur)

        grille = QVBoxLayout()
        grille.setSpacing(6)

        def ligne(label, valeur="", normaliser_adresses=False, multiligne=False):
            h = QHBoxLayout()
            lbl = QLabel(f"{label} :")
            lbl.setFixedWidth(60)
            if multiligne:
                champ = ChampDestinataires(valeur, normaliser_adresses=normaliser_adresses)
                # Clic sur "À :" / "Cc :" / "Cci :" = carnet d'adresses pour
                # ce champ (28/09/2026, demandé par l'utilisateur)
                lbl.setCursor(Qt.CursorShape.PointingHandCursor)
                lbl.setToolTip(f"Choisir des destinataires en {label} dans le carnet d'adresses")
                lbl.setStyleSheet("QLabel:hover { color: #e08080; text-decoration: underline; }")
                lbl.mousePressEvent = lambda event, c=champ, l=label: self._ouvrir_carnet_pour(c, l)
            else:
                champ = ChampTexteNatif(valeur, normaliser_adresses=normaliser_adresses)
            h.addWidget(lbl)
            h.addWidget(champ)
            grille.addLayout(h)
            return champ

        self.champ_a = ligne("À", destinataire, normaliser_adresses=True, multiligne=True)
        self.champ_cc = ligne("Cc", normaliser_adresses=True, multiligne=True)
        self.champ_cci = ligne("Cci", normaliser_adresses=True, multiligne=True)
        self.champ_sujet = ligne("Sujet", sujet)
        for champ_destinataire in (self.champ_a, self.champ_cc, self.champ_cci):
            installer_completion_destinataires(champ_destinataire)

