        # L'explication reste affichée même quand des pièces sont jointes.
        _btn_pj, self.lbl_invite_pj = construire_entete_colonne_pj(
            layout_colonne_pj, self._choisir_pieces_jointes)

        self._scroll_pj_compose = QScrollArea()
        self._scroll_pj_compose.setWidgetResizable(True)
        self._scroll_pj_compose.setFrameShape(QFrame.Shape.NoFrame)
        # Pas d'ascenseur horizontal (15/08/2026, bug remonté par
        # l'utilisateur — il cachait la croix de suppression en bas de
