        # le contenu débordait légèrement (des noms de fichiers très
        # numériques, ex. "image_2026-08-15_...", peuvent être visuellement
        # plus larges que leur nombre de caractères ne le laisse penser).
        self._scroll_pj_compose.setHorizontalScrollBarPolicy(Qt.ScrollBarPolicy.ScrollBarAlwaysOff)
        self._scroll_pj_compose.setStyleSheet("""
            QScrollBar:vertical { background: #000000; width: 32px; }
            QScrollBar::handle:vertical { background: #A52A2A; min-height: 20px; border-radius: 4px; margin: 6px;  subcontrol-origin: margin; }
            QScrollBar::handle:vertical:hover { background: #c03030; }
            QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0px; }
            QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: #000000; }
        """)
        self._conteneur_pj_compose = QWidget()
        self._conteneur_pj_compose.setStyleSheet("background: transparent;")
        self.layout_pj_compose = QVBoxLayout(self._conteneur_pj_compose)
        self.layout_pj_compose.setContentsMargins(0, 0, 0, 0)
        self.layout_pj_compose.setSpacing(6)
        self.layout_pj_compose.addStretch(1)
        self._scroll_pj_compose.setWidget(self._conteneur_pj_compose)
        layout_colonne_pj.addWidget(self._scroll_pj_compose, 1)

        layout_externe.addWidget(colonne_pj)

        # Ordre de tabulation explicite : À → Cc → Cci → Sujet → corps du mail
        # (la barre de mise en forme est volontairement exclue, cf. ClickFocus ci-dessus)
        self.setTabOrder(self.champ_a, self.champ_cc)
        self.setTabOrder(self.champ_cc, self.champ_cci)
        self.setTabOrder(self.champ_cci, self.champ_sujet)
