        self.pollers_graph = {}
        # Timers de relevé par compte {adresse: QTimer}
        self._timers_releve = {}
        self._releves_arriere_plan = []
        self._demarrer_timers_releve()
        self._idle_threads_zombies = []  # anciens threads IDLE en cours d'arrêt,
        # gardés en vie tant que Qt ne confirme pas qu'ils sont réellement
        # terminés (sinon : crash fatal "QThread: Destroyed while thread is
        # still running" si le ramasse-miettes les détruit en plein vol).
        self._synchroniseur_zombies = []  # même principe pour SynchroniseurCache
        self._chargeurs_zombies = []  # même principe pour ChargeurDossiers/ChargeurMessages,
        # remplacés à chaque changement de compte/dossier sans jamais vérifier
