        def _basculer_console2():
            try:
                import ctypes
                hwnd = ctypes.windll.kernel32.GetConsoleWindow()
                if hwnd == 0:
                    # Pas de console (lancement via pythonw.exe) : on en crée une
                    # à la demande et on y reconnecte stdout/stderr pour que les
                    # print() de diagnostic y apparaissent bien.
                    if ctypes.windll.kernel32.AllocConsole():
                        try:
                            nouvelle_console = open("CONOUT$", "w", encoding="utf-8", buffering=1)
                            if isinstance(sys.stdout, _FluxJournalise):
                                sys.stdout._flux_original = nouvelle_console
                            else:
                                sys.stdout = nouvelle_console
                            if isinstance(sys.stderr, _FluxJournalise):
                                sys.stderr._flux_original = nouvelle_console
                            else:
                                sys.stderr = nouvelle_console
                        except Exception:
                            pass
                else:
                    visible = ctypes.windll.user32.IsWindowVisible(hwnd)
                    ctypes.windll.user32.ShowWindow(hwnd, 0 if visible else 5)
            except Exception:
                pass
        btn_console.clicked.connect(_basculer_console2)
        layout_bas.addWidget(btn_console)

