        script_pont = script_pont.replace("__JS_TRADUCTION__", JS_TRADUCTION_DOM + JS_TRADUCTION_LECTURE)
        html_force = re.sub(r'(<meta charset="utf-8">)', r'\1' + script_pont.replace('\\', '\\\\'), html_force, count=1)
