    def _telecharger_image_survol(self, src):
        """Téléchargement en un clic d'une image du corps du mail (icône
        superposée injectée par _afficher_dans_cef). src est soit une URL
        file:// (cas le plus courant depuis le 27/07/2026 : image mise en
        cache disque dédupliqué par incorporer_images_distantes), soit une
        URI data: (ancien format, encore possible en repli si l'écriture
        disque échoue), soit une URL http(s) distante (repli si l'image n'a
        pas été mise en cache du tout).

        Depuis le 29/09/2026 (demandé par l'utilisateur) :
          - tout premier clic (aucun dossier "images" mémorisé) : boîte de
            choix du dossier, avec un texte explicatif ;
          - ensuite, UN clic : enregistrement direct dans ce dossier ;
          - DEUX clics : boîte de choix pour changer de dossier.
        Le badge envoie un appel par clic (JS du corps du mail et des pages
        externes) : le double-clic est donc reconnu ici, en retardant le
        clic simple du délai de double-clic de Windows."""
        from PySide6.QtWidgets import QApplication
        dossier_memo = (_charger_dossiers_enregistrement().get("images") or "").strip()
        if not dossier_memo:
            self._enregistrer_image_badge(src, avec_boite=True, premiere_fois=True)
            return
        timer = getattr(self, '_timer_clic_badge', None)
        if timer is not None and timer.isActive():
            # Deuxième clic dans le délai : double-clic
            timer.stop()
            self._enregistrer_image_badge(src, avec_boite=True)
            return
        if timer is None:
            timer = QTimer(self)
            timer.setSingleShot(True)
            timer.timeout.connect(lambda: self._enregistrer_image_badge(
                self._src_clic_badge, avec_boite=False))
            self._timer_clic_badge = timer
        self._src_clic_badge = src
        timer.start(QApplication.doubleClickInterval())

    def _enregistrer_image_badge(self, src, avec_boite, premiere_fois=False):
        """Enregistre l'image du badge vert, directement dans le dossier
        "images" mémorisé, ou après la boîte de choix (avec_boite, ou si
        le dossier mémorisé n'existe plus)."""
        import re as _re, datetime as _dt, urllib.parse as _up
        dossier_memo = (_charger_dossiers_enregistrement().get("images") or "").strip()
        if not avec_boite and dossier_memo and os.path.isdir(dossier_memo):
            if src.startswith("file:"):
                self._telecharger_image_fichier_local(src, dossier_memo)
            elif src.startswith("data:"):
                self._telecharger_image_data_uri(src, dossier_memo)
            elif src.startswith("http"):
                self._telecharger_image_navigateur(src, dossier_memo)
            else:
                self.label_statut.setText("  Impossible de télécharger cette image (adresse non reconnue).")
            return
        horodatage = _dt.datetime.now().strftime('%Y-%m-%d_%H%M%S')
        if src.startswith("file:"):
            m = _re.match(r'file:///(.+)', src)
            chemin_source = m.group(1).replace("/", os.sep) if m else ""
            extension = os.path.splitext(chemin_source)[1] or ".jpg"
            nom = f"image_{horodatage}{extension}"
            try:
                taille = f"{round(os.path.getsize(chemin_source)/1024, 1)} KB"
            except OSError:
                taille = ""
        elif src.startswith("data:"):
            nom = "image_" + horodatage
            taille = f"{round(len(src.split(',', 1)[-1]) * 3 / 4 / 1024, 1)} KB"
        elif src.startswith("http"):
            nom = os.path.basename(_up.unquote(_up.urlparse(src).path)) or "image"
            taille = ""
        else:
            self.label_statut.setText("  Impossible de télécharger cette image (adresse non reconnue).")
            return
        dossier = self._boite_choix_dossier(
            "Enregistrer les photos",
            "Photo à enregistrer :",
            [f"  {self._icone_pour_type(nom)}  {nom}" + (f"  ({taille})" if taille else "")],
            "Chemin où la photo sera enregistrée :",
            dossier_enregistrement("images"),
            explication=(
                "Vous cliquez pour la 1ère fois sur le badge image. Enregistrez le "
                "dossier de destination de votre téléchargement.\n\n"
                "Désormais il vous suffira d'UN SEUL clic sur le badge pour enregistrer "
                "automatiquement les photos dans le dossier que vous avez choisi.\n\n"
                "ATTENTION : si vous voulez modifier ce dossier de destination, il vous "
                "faudra désormais cliquer DEUX FOIS sur le badge pour ouvrir la boîte "
                "de dialogue et choisir un nouveau dossier. Et de nouveau vous pourrez "
                "enregistrer vos photos en un seul clic dans ce nouveau dossier."
            ) if premiere_fois else "",
        )
        if not dossier:
            return
        sauvegarder_dossier_enregistrement("images", dossier)
        if src.startswith("file:"):
            self._telecharger_image_fichier_local(src, dossier)
        elif src.startswith("data:"):
            self._telecharger_image_data_uri(src, dossier)
        else:
            self._telecharger_image_navigateur(src, dossier)

    def _telecharger_image_navigateur(self, url, dossier):
        """Image distante du badge vert (30/09/2026, lenteur remontée par
        l'utilisateur : le badge était bien plus lent que le clic droit
        "Enregistrer l'image"). Jusqu'ici passait par TelechargeurClicImage
        (urllib) qui RE-TÉLÉCHARGE l'image depuis le site, alors que le clic
        droit laisse Chromium la reprendre dans son cache — l'image est déjà
        affichée, donc déjà reçue. On demande donc le téléchargement au
        moteur web lui-même (QWebEnginePage.download) : il passe par
        downloadRequested (voir _gerer_telechargement dans main), qui
        consulte self._dl_badge_attendus pour l'enregistrer dans le dossier
        "images" plutôt que dans "telechargements"."""
        page = getattr(self, '_page_lecture', None)
        if page is None:
            self._telecharger_clic(url, dossier)
            return
        if not hasattr(self, '_dl_badge_attendus'):
            self._dl_badge_attendus = {}
        qurl = QUrl(url)
        # clé = forme normalisée par Qt, identique à item.url().toString()
        self._dl_badge_attendus[qurl.toString()] = dossier
        page.download(qurl)

    def _telecharger_image_fichier_local(self, url_file, dossier):
        """Copie une image déjà mise en cache localement (DOSSIER_CACHE_IMAGES)
        vers dossier — pendant de _telecharger_image_data_uri
        pour les images qui passent maintenant par le cache disque dédupliqué
        (27/07/2026) plutôt que par un embarquement en base64."""
        import re as _re, datetime as _dt, shutil as _shutil
        m = _re.match(r'file:///(.+)', url_file)
        if not m:
            self._statut_temporaire("  Échec du téléchargement de l'image (chemin non reconnu).")
            return
        chemin_source = m.group(1).replace("/", os.sep)
        if not os.path.exists(chemin_source):
            self._statut_temporaire("  Échec du téléchargement de l'image (fichier introuvable).")
            return
        # Sécurité (09/10/2026) : l'appel vient du JS de la page (pyBridge) —
        # ne copier que depuis les dossiers d'images de COURRIER, jamais un
        # fichier quelconque du disque désigné par un script de mail.
        reel = os.path.normcase(os.path.realpath(chemin_source))
        if not any(reel.startswith(os.path.normcase(os.path.realpath(d)) + os.sep)
                   for d in (DOSSIER_CACHE_IMAGES, DOSSIER_APERCU)):
            print(f"[SECURITE] Copie refusée hors du cache d'images : {chemin_source}")
            return
        extension = _extension_sure(chemin_source) or ".jpg"
        nom = f"image_{_dt.datetime.now().strftime('%Y-%m-%d_%H%M%S')}{extension}"
        chemin = os.path.join(dossier, nom)
        base_chemin, ext_chemin = os.path.splitext(chemin)
        n = 1
        while os.path.exists(chemin):
            chemin = f"{base_chemin} ({n}){ext_chemin}"
            n += 1
        try:
            _shutil.copy2(chemin_source, chemin)
            self._statut_temporaire(f"  Image téléchargée : {os.path.basename(chemin)}")
            config_dl = charger_son_telechargement()
            if config_dl.get("actif") and config_dl.get("chemin"):
                jouer_son_telechargement()
        except Exception as e:
            self._statut_temporaire(f"  Échec du téléchargement de l'image : {e}")

    def _telecharger_image_data_uri(self, data_uri, dossier):
        """Décode une image intégrée en base64 (data:...;base64,...) et
        l'enregistre dans dossier, avec
        la même protection anti-écrasement et le même son de fin que les
        autres téléchargements."""
        import base64, re as _re, datetime as _dt
        m = _re.match(r'data:([^;]+);base64,(.*)', data_uri, _re.DOTALL)
        if not m:
            self._statut_temporaire("  Échec du téléchargement de l'image (format non reconnu).")
            return
        mime = m.group(1).lower()
        EXTENSIONS_MIME_IMG = {
            "image/jpeg": ".jpg", "image/jpg": ".jpg", "image/png": ".png",
            "image/gif": ".gif", "image/webp": ".webp", "image/bmp": ".bmp",
            "image/svg+xml": ".svg",
        }
        extension = EXTENSIONS_MIME_IMG.get(mime, ".jpg")
        try:
            donnees = base64.b64decode(m.group(2))
        except Exception as e:
            self._statut_temporaire(f"  Échec du téléchargement de l'image : {e}")
            return
        nom = f"image_{_dt.datetime.now().strftime('%Y-%m-%d_%H%M%S')}{extension}"
        chemin = os.path.join(dossier, nom)
        base_chemin, ext_chemin = os.path.splitext(chemin)
        n = 1
        while os.path.exists(chemin):
            chemin = f"{base_chemin} ({n}){ext_chemin}"
            n += 1
        try:
            with open(chemin, "wb") as f:
                f.write(donnees)
            self._statut_temporaire(f"  Image téléchargée : {os.path.basename(chemin)}")
            config_dl = charger_son_telechargement()
            if config_dl.get("actif") and config_dl.get("chemin"):
                jouer_son_telechargement()
        except Exception as e:
            self._statut_temporaire(f"  Échec du téléchargement de l'image : {e}")

    def _telecharger_clic(self, url, dossier=None):
        """Lance le téléchargement silencieux d'un fichier cliqué dans le corps
        du mail (ou d'une image distante via le badge vert, dossier fourni)."""
        if dossier is None:
            dossier = getattr(self, '_dernier_chemin_pj', None)
            if not dossier or not os.path.isdir(dossier):
                dossier = CHEMIN_TELECHARGEMENT_DEFAUT if os.path.isdir(CHEMIN_TELECHARGEMENT_DEFAUT) else os.path.expanduser("~")
        self.label_statut.setText("  Téléchargement en cours…")
        if getattr(self, '_tele_clic', None) and self._tele_clic.isRunning():
            ancien_tele_clic = self._tele_clic
            try:
                ancien_tele_clic.termine.disconnect()
            except Exception:
                pass
            self._telechargeurs_clic_zombies.append(ancien_tele_clic)
            ancien_tele_clic.finished.connect(
                lambda t=ancien_tele_clic: self._telechargeurs_clic_zombies.remove(t)
                if t in self._telechargeurs_clic_zombies else None
            )
        self._tele_clic = TelechargeurClicImage(url, dossier)
        self._tele_clic.termine.connect(self._on_telechargement_clic_termine)
        self._tele_clic.start()

    def _on_telechargement_clic_termine(self, resultat, succes):
        if succes:
            nom = os.path.basename(resultat)
            self.label_statut.setText(f"  Téléchargé : {nom}")
            jouer_son_telechargement()
        else:
            self.label_statut.setText(f"  Échec du téléchargement : {resultat}")
        QTimer.singleShot(4000, self._maj_statut)

