    def gerer_spam(self):
        """Boîte de dialogue : liste complète des expéditeurs actuellement
        bloqués (redirigés automatiquement vers spam sur TOUS les comptes,
        voir ajouter_expediteurs_spam/retirer_expediteurs_spam) — jusqu'ici
        invisible autrement qu'en éditant expediteurs_spam.json à la main
        (16/09/2026, demandé par l'utilisateur suite à la découverte que
        compte@exemple.org s'y trouvait sans qu'il en ait eu
        connaissance). Permet de retirer un ou plusieurs expéditeurs
        (équivalent du bouton NON SPAM, sans avoir besoin d'un mail de cet
        expéditeur sous la main) et d'en ajouter manuellement."""
        from PySide6.QtWidgets import QDialog, QVBoxLayout, QHBoxLayout, QListWidget, QListWidgetItem, QLineEdit, QLabel
        dlg = QDialog(None)  # pas de parent Qt → fenêtre indépendante + bouton taskbar auto
        dlg.setWindowTitle("EXPÉDITEURS BLOQUÉS")
        dlg.setWindowFlags(
            Qt.WindowType.Window |
            Qt.WindowType.WindowTitleHint |
            Qt.WindowType.WindowCloseButtonHint |
            Qt.WindowType.WindowMinimizeButtonHint |
            Qt.WindowType.WindowMaximizeButtonHint
        )
        dlg.setMinimumSize(520, 560)
        dlg.setStyleSheet("""
            QDialog, QWidget { background-color: #2a2a2a; color: white; font-family: Verdana; font-size: 11px; }
            QListWidget { background-color: #1e1e1e; color: white; border: 1px solid #5a5a5a; outline: none; }
            QListWidget::item { padding: 6px 8px; }
            QListWidget::item:selected { background-color: #A52A2A; color: white; }
            QListWidget::item:hover { background-color: #A52A2A; color: white; }
            QLineEdit { background-color: #1e1e1e; color: white; border: 1px solid #5a5a5a; padding: 4px 6px; selection-background-color: #A52A2A; selection-color: white; }
            QLabel { color: white; }
        """ + STYLE_BOUTON + STYLE_SCROLLBAR)

        layout = QVBoxLayout(dlg)
        layout.setContentsMargins(15, 15, 15, 15)
        layout.setSpacing(10)

        lbl_titre = QLabel(
            "Expéditeurs redirigés automatiquement vers spam, sur TOUS les comptes")
        lbl_titre.setStyleSheet("color: white; font-weight: bold; font-size: 12px;")
        lbl_titre.setWordWrap(True)
        layout.addWidget(lbl_titre)

        liste_widget = QListWidget()
        liste_widget.setSelectionMode(QListWidget.SelectionMode.ExtendedSelection)
        layout.addWidget(liste_widget)

        lbl_nb = QLabel("")
        lbl_nb.setStyleSheet("color: #aaaaaa;")
        layout.addWidget(lbl_nb)

        def _recharger():
            liste_widget.clear()
            for entree in sorted(charger_expediteurs_spam()):
                liste_widget.addItem(QListWidgetItem(entree))
            lbl_nb.setText(f"{liste_widget.count()} expéditeur(s) bloqué(s)")
        _recharger()

        ligne_ajout = QHBoxLayout()
        champ_ajout = QLineEdit()
        champ_ajout.setPlaceholderText("adresse@exemple.fr — Entrée ou bouton pour ajouter")
        btn_ajouter = QPushButton(" Ajouter ")
        btn_ajouter.setStyleSheet(STYLE_BOUTON)
        def _ajouter():
            valeur = champ_ajout.text().strip()
            if valeur:
                ajouter_expediteurs_spam({valeur})
                champ_ajout.clear()
                _recharger()
        champ_ajout.returnPressed.connect(_ajouter)
        btn_ajouter.clicked.connect(_ajouter)
        ligne_ajout.addWidget(champ_ajout)
        ligne_ajout.addWidget(btn_ajouter)
        layout.addLayout(ligne_ajout)

        layout_btn = QHBoxLayout()
        btn_retirer = QPushButton(" Retirer la sélection ")
        btn_retirer.setStyleSheet(STYLE_BOUTON)
        def _retirer():
            selection = {it.text() for it in liste_widget.selectedItems()}
            if not selection:
                return
            retirer_expediteurs_spam(selection)
            _recharger()
            # Garde-fou (16/09/2026, remonté par l'utilisateur) : débloquer
            # une adresse ici n'empêchait jusqu'ici que les FUTURS mails
            # d'être redirigés — ceux déjà présents dans le dossier spam
            # d'un compte restaient introuvables, comme si le déblocage
            # n'avait servi à rien. On lance donc une recherche/rapatriement
            # en arrière-plan sur tous les comptes IMAP (voir
            # RestaurateurDepuisSpam), sans bloquer la fenêtre.
            btn_retirer.setEnabled(False)
            lbl_nb.setText(f"{liste_widget.count()} expéditeur(s) bloqué(s) — "
                            f"recherche des mails déjà en spam...")
            if not hasattr(self, '_restaurateurs_spam_en_cours'):
                self._restaurateurs_spam_en_cours = []
            restaurateur = RestaurateurDepuisSpam(COMPTES, selection)
            self._restaurateurs_spam_en_cours.append(restaurateur)
            def _sur_fin_restauration(nb, t=restaurateur):
                if t in self._restaurateurs_spam_en_cours:
                    self._restaurateurs_spam_en_cours.remove(t)
                try:
                    btn_retirer.setEnabled(True)
                    if nb:
                        lbl_nb.setText(f"{liste_widget.count()} expéditeur(s) bloqué(s) — "
                                        f"{nb} mail(s) rapatrié(s) depuis spam vers la boîte "
                                        f"de réception")
                    else:
                        lbl_nb.setText(f"{liste_widget.count()} expéditeur(s) bloqué(s) — "
                                        f"aucun mail de cet/ces expéditeur(s) trouvé en spam")
                except RuntimeError:
                    pass  # fenêtre déjà fermée entre-temps
            restaurateur.termine.connect(_sur_fin_restauration)
            restaurateur.start()
        btn_retirer.clicked.connect(_retirer)
        btn_fermer_spam = QPushButton(" Fermer ")
        btn_fermer_spam.setStyleSheet(STYLE_BOUTON)
        btn_fermer_spam.clicked.connect(dlg.reject)
        layout_btn.addWidget(btn_retirer)
        layout_btn.addWidget(btn_fermer_spam)
        layout.addLayout(layout_btn)

        dlg.show()
        self._conserver_fenetre_secondaire(dlg)

    def _gerer_comptes_impl(self):
        from PySide6.QtWidgets import QDialog, QVBoxLayout, QHBoxLayout, QListWidget, QListWidgetItem, QLineEdit, QLabel, QFormLayout, QComboBox
        dlg = QDialog(None)  # pas de parent Qt → fenêtre indépendante + bouton taskbar auto
        dlg.setWindowTitle("COMPTES")
        dlg.setWindowFlags(
            Qt.WindowType.Window |
            Qt.WindowType.WindowTitleHint |
            Qt.WindowType.WindowCloseButtonHint |
            Qt.WindowType.WindowMinimizeButtonHint |
            Qt.WindowType.WindowMaximizeButtonHint
        )
        dlg.setMinimumSize(560, 900)
        dlg.setStyleSheet("""
            QDialog, QWidget { background-color: #2a2a2a; color: white; font-family: Verdana; font-size: 11px; }
            QListWidget { background-color: #1e1e1e; color: white; border: 1px solid #5a5a5a; outline: none; }
            QListWidget::item { padding: 6px 8px; }
            QListWidget::item:selected { background-color: #A52A2A; color: white; }
            QListWidget::item:hover { background-color: #A52A2A; color: white; }
            QLineEdit, QComboBox { background-color: #1e1e1e; color: white; border: 1px solid #5a5a5a; padding: 4px 6px; selection-background-color: #A52A2A; selection-color: white; }
            QComboBox QAbstractItemView { background-color: #1e1e1e; color: white; selection-background-color: #A52A2A; }
            QLabel { color: #aaaaaa; }
        """ + STYLE_BOUTON + STYLE_SCROLLBAR)

        layout = QVBoxLayout(dlg)
        layout.setContentsMargins(15, 15, 15, 15)
        layout.setSpacing(10)

        # Liste des comptes
        lbl_liste = QLabel("Comptes configurés :")
        lbl_liste.setStyleSheet("color: white; font-weight: bold;")
        layout.addWidget(lbl_liste)

        liste = QListWidget()
        for c in COMPTES:
            liste.addItem(QListWidgetItem(f"  {c['nom']}  —  {c['adresse']}"))
        layout.addWidget(liste)

        # Monter/Descendre (17/08/2026, demandé — même principe que pour
        # organiser l'ordre des dossiers). Modifie directement COMPTES (la
        # liste globale, source de vérité pour l'ordre d'affichage partout
        # dans l'appli) puis répercute immédiatement dans la fenêtre
        # principale via _maj_liste_comptes(), sans attendre un redémarrage.
        ligne_deplacement = QHBoxLayout()
        ligne_deplacement.setSpacing(6)
        btn_monter_compte = QPushButton("▲ Monter")
        btn_descendre_compte = QPushButton("▼ Descendre")
        for b in (btn_monter_compte, btn_descendre_compte):
            b.setStyleSheet(STYLE_BOUTON)
            ligne_deplacement.addWidget(b)
        layout.addLayout(ligne_deplacement)

        def _deplacer_compte(delta):
            row = liste.currentRow()
            nouvelle_row = row + delta
            if row < 0 or not (0 <= nouvelle_row < len(COMPTES)):
                return
            COMPTES[row], COMPTES[nouvelle_row] = COMPTES[nouvelle_row], COMPTES[row]
            sauvegarder_comptes(COMPTES)
            liste.clear()
            for c in COMPTES:
                liste.addItem(QListWidgetItem(f"  {c['nom']}  —  {c['adresse']}"))
            liste.setCurrentRow(nouvelle_row)
